L["the welcome window, to pick a profile"] = "프로필을 고르는 환영 창"
L["Frames (hover over one first)"] = "창 (먼저 마우스를 올리세요)"
L["fade it too (or /cine add <FrameName>)"] = "이 창도 흐리게 하기 (또는 /cine add <창이름>)"
L["pick up every frame you hover over, then again to fade them all"] = "마우스를 올리는 창을 모두 고르고, 다시 입력하면 모두 흐리게 하기"
L["always show it"] = "항상 표시하기"
