L["turn the camera slowly around to look back, then back behind you (again to stop)"] = "카메라를 천천히 돌려 뒤를 돌아보고, 다시 뒤쪽으로 (다시 입력하면 멈춤)"
L["does the addon think you're walking or auto-running?"] = "애드온은 지금 걷기 중으로 볼까요, 자동 달리기 중으로 볼까요?"
L["fix it if it has walk and run backwards"] = "걷기와 달리기를 반대로 알고 있으면 바로잡기"
L["More"] = "더 보기"
L["troubleshooting commands"] = "문제 해결 명령어"
L["copy the log and your setup for a bug report (/cine log clear empties it)"] = "버그 보고용으로 로그와 설정 복사 (/cine log clear로 비움)"
L["stop for this session and put your UI and settings back (/cine resume to restart)"] = "이번 접속 동안 중지하고 UI와 설정을 원래대로 (/cine resume으로 다시 시작)"
L["Keybinds (toggle CineMode, hide the UI, start a camera) are on the Keybinds settings page."] = "단축키(CineMode 켜기/끄기, UI 숨기기, 카메라 시작)는 단축키 설정 페이지에 있습니다."
L["log cleared"] = "로그를 비웠습니다"
