L["Can't be interrupted"] = "차단 불가"
L["Can't find them now: target them, or get them on screen, to see their talents."] = "지금은 찾을 수 없습니다: 특성을 보려면 대상으로 지정하거나 화면 안에 들어오게 하세요."
L["Can't inspect them from here: too far away, or gone."] = "여기서는 살펴볼 수 없습니다: 너무 멀거나 사라졌습니다."
L["Can't: %s. Open the rule to change it, or Reset to grid there."] = "불가: %s. 바꾸려면 규칙을 열거나, 거기서 '격자로 초기화'를 하세요."
