L["Changes go in your profile %s."] = "변경 사항은 내 프로필 %s에 저장됩니다."
L["Changes go in your profile %s. This part is a mix of its own."] = "변경 사항은 내 프로필 %s에 저장됩니다. 이 부분은 자체 조합입니다."
