L["Clean Up Bags leaves the part stack of arrows or bullets last, but you shoot from the first stack, so a full one would run down and leave you with two part stacks. Once the bags are cleaned up, the smallest stack is moved first, to be shot first."] = "가방 정리는 덜 찬 화살이나 탄환 묶음을 맨 뒤에 두지만, 사격은 첫 묶음부터 쓰므로 가득 찬 묶음이 줄어 덜 찬 묶음이 두 개가 됩니다. 가방 정리가 끝나면 가장 작은 묶음을 앞으로 옮겨 먼저 쏘게 합니다."
L["Clear"] = "비우기"
L["Clear all data"] = "모든 데이터 지우기"
L["Clear the Profiler's graph and its last recording, here and in what's saved? (The game's own figures for each addon start again only when the game does.)"] = "프로파일러의 그래프와 마지막 기록을 여기와 저장된 곳에서 지우시겠습니까? (애드온별 게임 자체 수치는 게임을 다시 시작해야 새로 셉니다.)"
L["Cleared"] = "지워짐"
L["Clears the graph's samples and the last recording, here and in what's saved."] = "그래프 표본과 마지막 기록을 여기와 저장된 곳에서 지웁니다."
L["Clears this shot's numbers, so each follows its camera's own setting again."] = "이 샷의 수치를 지워서 각각 다시 카메라 자체 설정을 따르게 합니다."
L["Click a group's icon below to go to it, or the + to make one of your own."] = "아래 그룹 아이콘을 클릭해 그 그룹으로 가거나, +를 눌러 나만의 그룹을 만드세요."
L["Click a line to open its setting. Click another frame to look at it."] = "줄을 클릭하면 그 설정이 열립니다. 다른 창을 클릭하면 그 창을 살펴봅니다."
