L["Dawn, Morning, Midday, Afternoon, Evening, Dusk or Night as you log in or reload: over the name on this card, or under the game's zone name with Zone unticked. Follows the clock picked on the Tint page."] = "접속하거나 다시 불러올 때 새벽, 아침, 한낮, 오후, 저녁, 해 질 녘 또는 밤: 이 카드의 이름 위에, 또는 '지역'을 해제했다면 게임의 지역 이름 아래에. 색조 페이지에서 고른 시계를 따릅니다."
