L["Follow: after you turn, glide behind you (after %s s still)"] = "따라가기: 방향을 바꾼 뒤 뒤쪽으로 부드럽게 돌아가기(%s초 정지 후)"
L["Follows %s"] = "%s 따름"
L["Follows %s: shows when it does. Its own settings are kept for when it stops."] = "%s 따름: 그것이 보일 때 보입니다. 따르기를 멈출 때를 위해 자체 설정은 보관됩니다."
