L["Soft wisps of heat rising from the bottom of the screen, flickering, higher the weaker you are. Fire themes have it."] = "화면 아래에서 피어오르며 일렁이는 부드러운 열기, 약해질수록 높이 오릅니다. 불 테마에 있습니다."
L["Soft, thin bars with a fine edge, health in your class color."] = "가는 테두리의 부드럽고 얇은 바, 직업 색 생명력."
L["Some nameplate and name changes only take effect once the fight ends."] = "일부 이름표와 이름 변경은 전투가 끝난 뒤에야 적용됩니다."
L["Something has been taking the turnips at night, and nobody here is brave enough to keep watch. Would you?"] = "밤마다 무언가가 순무를 가져가는데, 여기엔 망을 볼 만큼 용감한 사람이 없어요. 해 주시겠어요?"
