L["Speech from behind you shows here.\nDrag it where you want it, left-click to set, right-click to reset."] = "뒤에서 들리는 대사가 여기 나옵니다.\n원하는 곳으로 끌고, 왼쪽 클릭으로 정하고, 오른쪽 클릭으로 초기화하세요."
L["Speech from behind you starts with the speaker's name (\"Name says: ...\"). Unticked, just their words show."] = "뒤에서 들리는 대사 앞에 말한 사람 이름을 붙입니다(\"이름의 말: ...\"). 해제하면 말만 나옵니다."
