L["Starts the RP walk camera now, walking or not. Press again to stop it; its stop rules (its Scripts page) say what else does."] = "걷든 안 걷든 지금 RP 걷기 카메라를 시작합니다. 다시 누르면 멈춥니다. 그 밖에 무엇이 멈추는지는 멈춤 규칙(스크립트 페이지)이 정합니다."
L["Starts the auto-run camera now, running or not. Press again to stop it; its stop rules (its Scripts page) say what else does."] = "달리든 안 달리든 지금 자동 달리기 카메라를 시작합니다. 다시 누르면 멈춥니다. 그 밖에 무엇이 멈추는지는 멈춤 규칙(스크립트 페이지)이 정합니다."
L["Starts when you close the settings: %d seconds, detailed."] = "설정을 닫으면 시작: %d초, 상세."
