L["Stop the camera"] = "카메라 멈추기"
L["Stopped. Run plays it again."] = "중지됨. '실행'으로 다시 재생합니다."
L["Stops following: its own ticks or rule, as they were, decide again."] = "따르기를 멈춥니다: 원래 체크나 규칙이 다시 정합니다."
