L["Stuck, or something looks wrong? Read up in the guide, or report it to us. Click a link and press Ctrl+C to copy it, then paste it into your browser (addons can't open one)."] = "막혔거나 뭔가 이상한가요? 안내서를 읽어 보거나 우리에게 알려 주세요. 링크를 클릭하고 Ctrl+C로 복사한 뒤 브라우저에 붙여 넣으세요(애드온은 브라우저를 열 수 없습니다)."
