L["Target the last speaker"] = "마지막으로 말한 NPC 대상 지정"
L["Targets the last NPC who spoke near you (your character turns their head to them). Addons can't target on their own: the game only lets a key press do it. Out of fights."] = "근처에서 마지막으로 말한 NPC를 대상으로 지정합니다(캐릭터가 그쪽으로 고개를 돌림). 애드온은 스스로 대상을 지정할 수 없고, 게임은 키 누름으로만 허용합니다. 비전투 중에만."
L["Tele Vision"] = "Tele Vision"
L["Tele Vision colors: %d specs, %d seconds each (/cine teleport colors again to stop)."] = "Tele Vision 색: 전문화 %d개, 각 %d초(멈추려면 /cine teleport colors를 다시 입력)."
L["Tele Vision colors: all %d shown."] = "Tele Vision 색: %d개 모두 표시함."
L["Tele Vision colors: stopped."] = "Tele Vision 색: 중지됨."
L["Terrain detail distance"] = "지형 세부 묘사 거리"
L["Territory"] = "영토"
L["Test"] = "시험"
L["Test item"] = "시험 아이템"
