L["Units"] = "유닛"
L["Unloaded"] = "불러오지 않음"
L["Untick to leave the camera running when this happens. Moving the camera yourself still takes over: it carries on a second after you let go."] = "이런 일이 있을 때 카메라를 계속 돌게 하려면 해제하세요. 직접 카메라를 움직이면 여전히 넘겨받습니다: 놓은 뒤 1초 후 이어 갑니다."
L["Until %s s before landing"] = "착륙 %s초 전까지"
L["Until %s s go by"] = "%s초가 지날 때까지"
L["Until someone new talks"] = "새로운 사람이 말할 때까지"
L["Until the cast ends"] = "시전이 끝날 때까지"
L["Until the cast is %s s from done"] = "시전 완료 %s초 전까지"
L["Until you're back to life"] = "되살아날 때까지"
L["Use General"] = "일반 사용"
L["Use Visions Style"] = "Visions 스타일 사용"
L["Use default settings"] = "기본 설정 사용"
L["Use the camera's own numbers"] = "카메라 자체 수치 사용"
L["Use the quest item"] = "퀘스트 아이템 사용"
L["Use this row. Unticked, its trigger passes it over: the next row for it is tried, and with none it starts no camera. Its settings stay for when you tick it again."] = "이 줄을 사용합니다. 해제하면 발동 조건이 이 줄을 건너뛰고 다음 줄을 시도하며, 없으면 카메라를 시작하지 않습니다. 다시 체크할 때를 위해 설정은 유지됩니다."
L["Used by: %s"] = "사용처: %s"
L["Uses the item on Quest Vision's quest item button, while it shows."] = "Quest Vision의 퀘스트 아이템 버튼이 보이는 동안 그 아이템을 사용합니다."
L["Usual order"] = "평소 순서"
L["Utility"] = "보조"
L["Utility Cooldowns"] = "보조 재사용 대기시간"
L["Utility: stay up while a cooldown is recharging"] = "보조: 재사용 대기시간이 충전되는 동안 유지"
L["Version %s, %d settings changed"] = "버전 %s, 바꾼 설정 %d개"
L["Victory"] = "승리"
L["View distance"] = "시야 거리"
L["Vision"] = "Vision"
L["Vision wheel"] = "Vision 휠"
L["Visions"] = "Visions"
L["Visions Style"] = "Visions 스타일"
L["Visions in use"] = "사용 중인 Vision"
L["Vitals Vision"] = "Vitals Vision"
L["Vitals Vision demo stopped."] = "Vitals Vision 시연 중지됨."
L["Vitals Vision demo: a new theme every %s seconds (/cine vital demo to stop)."] = "Vitals Vision 시연: %s초마다 새 테마(멈추려면 /cine vital demo)."
L["Vitals Vision demo: all %d shown."] = "Vitals Vision 시연: %d개 모두 표시함."
