-- Options.lua
L["(game: %s)"] = "(게임: %s)"
L["While the fish camera is on and no bobber is out, right-clicking in the world casts Fishing again. Each cast still comes from your own click. While the bobber is out, right-click clicks it as usual (or reels in from anywhere: see below); in combat, with the loot window open or with your mouse on a player or NPC, right-click is left alone. (Meanwhile right-drag doesn't turn the camera: left-drag still does.)"] = "낚시 카메라가 켜져 있고 찌가 없는 동안, 세계를 오른쪽 클릭하면 낚시를 다시 던집니다. 던지기는 여전히 매번 당신의 클릭으로 이루어집니다. 찌가 떠 있는 동안 오른쪽 클릭은 평소처럼 찌를 클릭합니다(또는 어디서든 건져 올립니다: 아래 참고). 전투 중, 전리품 창이 열려 있을 때, 마우스가 플레이어나 NPC 위에 있을 때는 오른쪽 클릭을 건드리지 않습니다. (그동안 오른쪽 드래그로는 카메라가 돌지 않습니다: 왼쪽 드래그는 됩니다.)"
L["Right-click to reel in"] = "오른쪽 클릭으로 건지기"
L["While the bobber is out, right-clicking anywhere in the world reels it in, with no need to find the bobber with the mouse (in gamepad mode, the cast button below does too). It uses the game's \"Interact with target\" key, so the game's soft targeting of objects is on while you fish, and your own setting comes back after. Reeling in before a bite ends the cast. Not in combat or with your mouse on a player or NPC. (While the bobber is out, right-drag doesn't turn the camera: left-drag still does.)"] = "찌가 떠 있는 동안 세계 어디든 오른쪽 클릭하면 찌를 건져 올립니다. 마우스로 찌를 찾을 필요가 없습니다(게임패드 모드에서는 아래의 던지기 버튼도 마찬가지). 게임의 \"대상과 상호작용\" 키를 쓰므로 낚시하는 동안 게임의 사물 소프트 타겟팅이 켜지고, 끝나면 당신의 설정이 돌아옵니다. 입질 전에 건지면 던지기가 끝납니다. 전투 중이거나 마우스가 플레이어나 NPC 위에 있을 때는 아닙니다. (찌가 떠 있는 동안 오른쪽 드래그로는 카메라가 돌지 않습니다: 왼쪽 드래그는 됩니다.)"
L["The key you cast with reels in too"] = "던진 키로도 건지기"
L["With Fishing on an action bar (the spell, or a macro that casts it), its key reels the bobber in while it's out, rather than casting again: press 1 to cast, then 1 again to reel in. Works on the game's own action bars. Uses the game's soft targeting of objects, as right-click does. Not in combat."] = "행동 단축바에 낚시(주문 자체나 그것을 시전하는 매크로)가 있으면, 찌가 떠 있는 동안 그 키가 다시 던지는 대신 찌를 건져 올립니다: 1로 던지고 다시 1로 건집니다. 게임 자체의 행동 단축바에서 작동합니다. 오른쪽 클릭처럼 게임의 사물 소프트 타겟팅을 씁니다. 전투 중에는 아닙니다."
L["Show"] = "표시"
L["Names and titles: a service NPC's name shows on its nameplate with its title under it. Titles only: just its title (<Repair Vendor>) where its name would be, unless its own row (or your target's) shows its name too. Beyond nameplate range, and in dungeons and raids, the game shows names and titles together."] = "이름과 직함: 서비스 NPC의 이름이 이름표에 보이고 그 아래에 직함이 보입니다. 직함만: 자기 줄(또는 대상의 줄)이 이름도 보여주지 않는 한, 이름 자리에 직함(<방어구 제작자>)만 보입니다. 이름표 범위 밖과 던전·공격대에서는 게임이 이름과 직함을 함께 보여줍니다."
L["Names and titles"] = "이름과 직함"
L["Titles only"] = "직함만"
L["Kinds"] = "종류"
L["Any other title, lore titles too (<Ranger-General of Silvermoon>)."] = "그 밖의 모든 직함, 설정상 직함도 포함(<실버문의 순찰대장>)."
L["NPCs whose title has one of these words in it: %s."] = "직함에 다음 단어 중 하나가 든 NPC: %s."
L["Raise"] = "올리기"
L["Not your kill"] = "내 몫 아님"
L["An NPC someone outside your group hit first: killing it gives you no loot, experience or quest credit. Its name and health bar gray to start with."] = "당신 파티 밖의 누군가가 먼저 공격한 NPC: 죽여도 전리품, 경험치, 퀘스트 진행을 얻지 못합니다. 이름과 생명력 바는 처음부터 회색입니다."
L["Out of range"] = "사거리 밖"
L["out of range"] = "사거리 밖"
L["This row: just those about that far from you. 11 and 28 yards are the game's interact distances; 40 asks a 40-yard spell on your action bars (harmful for enemies, helpful for friends), and with none there the row fits no unit past 28 yards. Out of range: none of the spells on your action bars reaches it (attacks for enemies, helpful spells for friends), as their buttons turn red."] = "이 줄: 당신에게서 대략 그만큼 떨어진 것만. 11m와 28m는 게임의 상호작용 거리이고, 40은 행동 단축바의 40m 주문(적에게는 해로운 주문, 아군에게는 이로운 주문)에 물어보며, 그런 주문이 없으면 이 줄은 28m 밖의 어떤 유닛에도 맞지 않습니다. 사거리 밖: 행동 단축바의 어떤 주문도 닿지 않는 경우(적에게는 공격, 아군에게는 이로운 주문)로, 버튼이 빨갛게 될 때와 같습니다."
L["Any distance: all of them, near or far. Within or past 11, 28 or 40 yards: just those that far from you, say Any unit past 40 yards to fade the plates far off. 40 yards asks a 40-yard spell on your action bars; with none there, the row fits no unit past 28 yards. Out of range: none of the spells on your action bars reaches them, as their buttons turn red."] = "모든 거리: 가깝든 멀든 전부. 11, 28, 40m 이내 또는 밖: 그만큼 떨어진 것만. 예를 들어 '40m 밖의 모든 유닛'으로 먼 이름표를 흐리게 합니다. 40m는 행동 단축바의 40m 주문에 물어보며, 그런 주문이 없으면 이 줄은 28m 밖의 어떤 유닛에도 맞지 않습니다. 사거리 밖: 행동 단축바의 어떤 주문도 닿지 않는 경우로, 버튼이 빨갛게 될 때와 같습니다."
L["Raise with a plate"] = "이름표와 함께 올리기"
L["Reveal shows"] = "표시 시 보이는 것"
L["Everything"] = "전부"
L["Just the map"] = "지도만"
L["Map"] = "지도"
L["When a ping, a reveal below or Keep open's tracking brings the faded minimap up, only the map comes up with what's ticked here; the rest of the header stays faded. Hovering the minimap shows it all."] = "알림, 아래의 표시 또는 계속 열기의 추적이 흐려진 미니맵을 띄울 때, 여기서 체크한 것과 함께 지도만 나타납니다. 나머지 머리 부분은 흐린 채로 남습니다. 미니맵에 마우스를 올리면 전부 보입니다."
L["The buffs this bar shows sit together in their order, centered on the bar, instead of inactive or faded ones leaving gaps. Edit Mode shows the game's own layout."] = "이 바가 보여주는 강화 효과는 순서대로 모여 바 가운데에 놓이고, 비활성이거나 흐려진 것이 빈자리를 남기지 않습니다. 편집 모드에서는 게임 자체의 배치가 보입니다."
L["Picking a vendor's \"let me browse your goods\", the shop window opens where the talk was, on the other half of the screen from the NPC, instead of where the game puts it. A shop opened straight from a right click on the vendor opens where the game puts it. Drag it and it stays where you drop it until it closes."] = "상인에게서 \"물건을 보여 주세요\"를 고르면, 게임이 두는 자리 대신 대화하던 자리, NPC 반대쪽 화면 절반에 상점 창이 열립니다. 상인을 오른쪽 클릭해 바로 연 상점은 게임이 두는 자리에 열립니다. 창을 드래그하면 닫힐 때까지 놓은 자리에 있습니다."
L["Add all"] = "모두 추가"
L["Fades every frame on this list that isn't added yet, as Add does for one."] = "이 목록에서 아직 추가하지 않은 모든 창을 흐리게 합니다. 하나에 대해 추가가 하는 것과 같습니다."
L["Brings the letterbox bars in, or takes them out, in or out of CineMode. Turning CineMode on or off puts them back as the Letterbox page says."] = "CineMode 안팎에서 레터박스를 들여오거나 내보냅니다. CineMode를 켜거나 끄면 레터박스 페이지 설정대로 돌아갑니다."

-- SwingTimerStyle.lua, DamageMeterStyle.lua (Interface Recolor rows)
L["Damage meter"] = "피해량 측정기"
L["Frame color"] = "테두리 색상"
L["The game's damage meter's borders, header and buttons in the theme's color. Its bars keep their colors."] = "게임 피해량 측정기의 테두리, 머리글, 버튼을 테마 색상으로 바꿉니다. 막대는 원래 색상을 유지합니다."
L["Bar texture"] = "막대 텍스처"
L["Its bars in General's bar texture, each in its own color."] = "막대를 일반의 막대 텍스처로 바꾸며, 각 막대는 고유 색상을 유지합니다."
L["Text font"] = "글꼴"
L["Its names and numbers in General's text font."] = "이름과 숫자를 일반의 글꼴로 표시합니다."
L["The swing timer bars' frames in the theme's color. What fills them keeps its color."] = "평타 타이머 막대의 테두리를 테마 색상으로 바꿉니다. 채워지는 부분은 원래 색상을 유지합니다."
L["The bars' fill in General's bar texture, each weapon's in its own color."] = "막대 채움을 일반의 막대 텍스처로 바꾸며, 무기마다 고유 색상을 유지합니다."
L["The bars' words in General's text font."] = "막대의 글자를 일반의 글꼴로 표시합니다."

-- Shoulder Cam (ShoulderCam.lua, ShoulderCalibrate.lua, ProfileChoices.lua): public since 2026-11-15
L["The Shoulder Cam uses one of Blizzard's experimental camera settings. The game would warn about it every time you log in, so Cinematic keeps that warning away while the Shoulder Cam is on. If the camera ever acts up, turn the Shoulder Cam off and your own camera settings come back."] = "어깨 카메라는 Blizzard의 실험적 카메라 설정 중 하나를 사용합니다. 게임은 접속할 때마다 이에 대해 경고하므로, 어깨 카메라가 켜져 있는 동안 Cinematic이 그 경고를 막아 줍니다. 카메라가 이상하게 동작하면 어깨 카메라를 끄세요. 원래 카메라 설정이 돌아옵니다."
L["Accept"] = "수락"
L["Shoulder Cam is paused while the gamepad UI is on: the game keeps your character centered in it."] = "게임패드 UI가 켜져 있는 동안 어깨 카메라는 일시 정지됩니다: 게임이 캐릭터를 화면 가운데에 고정합니다."
L["Swap shoulders (Shoulder Cam)"] = "어깨 전환 (어깨 카메라)"
L["On: the camera moves over your shoulder. This uses one of Blizzard's experimental camera settings: Cinematic asks once, then keeps the game's experimental camera warning away while it's on. The game's Keep Character Centered and motion sickness options stop it, so those are turned off meanwhile. Off: your own settings come back."] = "켜짐: 카메라가 어깨 너머로 이동합니다. Blizzard의 실험적 카메라 설정 중 하나를 사용합니다: Cinematic이 한 번 묻고, 켜져 있는 동안 게임의 실험적 카메라 경고를 막아 줍니다. 게임의 '캐릭터 가운데 유지'와 멀미 방지 옵션이 이를 막으므로 그동안 꺼집니다. 꺼짐: 원래 설정이 돌아옵니다."
L["Where the camera sits, when it turns, and when it steps back behind you."] = "카메라가 어디에 있는지, 언제 돌아가는지, 언제 뒤로 물러나는지."
L["Follow HUD"] = "따라오는 HUD"
L["The frames that follow you: which slide with you as the camera sits over your shoulder."] = "따라오는 프레임: 카메라가 어깨 너머에 있는 동안 어떤 프레임이 함께 미끄러지는지."
L["Which of Cinematic's cameras the Shoulder Cam stays on through."] = "어깨 카메라가 Cinematic의 어떤 카메라 동안 유지되는지."
L["Playing with the gamepad UI on."] = "게임패드 UI를 켜고 플레이."
L["Calibrate"] = "보정"
L["Measure where you sit for your race, sex and form, and share it."] = "종족, 성별, 형상별로 화면에서 내 위치를 측정하고 공유하세요."
L["Over your left shoulder, you on the right of the screen. Unticked, over your right. The swap key beside it flips it."] = "왼쪽 어깨 너머, 나는 화면 오른쪽에. 체크 해제 시 오른쪽 어깨 너머. 옆의 전환 키로 바꿉니다."
L["Spot on screen"] = "화면 위치"
L["How far off the middle of the screen you sit, as a share of the way to its edge. The camera moves as you zoom to keep you there, and eases you back to the middle when you zoom right in. 33% puts you on the line a third of the way across."] = "화면 가운데에서 얼마나 떨어져 있는지, 가장자리까지 거리의 비율로. 확대/축소할 때 카메라가 움직여 그 자리를 유지하고, 완전히 확대하면 부드럽게 가운데로 돌려놓습니다. 33%면 폭의 3분의 1 지점 선에 놓입니다."
L["Swap takes"] = "전환 시간"
L["How long the camera takes to cross to your other shoulder as you swap sides. At 0 it's the game's own quick swap."] = "쪽을 바꿀 때 카메라가 반대쪽 어깨로 넘어가는 데 걸리는 시간. 0이면 게임 자체의 빠른 전환입니다."
L["Back from targeting yourself"] = "자신 대상 지정 후 복귀"
L["With yourself targeted the game puts you in the middle of the screen, at once. This is how long the camera takes to go back over your shoulder as you clear the target."] = "자신을 대상으로 지정하면 게임이 즉시 화면 가운데로 옮깁니다. 대상을 해제할 때 카메라가 다시 어깨 너머로 돌아오는 데 걸리는 시간입니다."
L["Off and on again takes"] = "꺼졌다 다시 켜지는 시간"
L["How long the camera takes to go back behind you as you go indoors, mount, or leave where Show in has it, and back over your shoulder after. Cinematic's own cameras have their own times on the Cameras tab."] = "실내에 들어가거나, 탈것에 타거나, '표시 장소'가 켜 둔 곳을 벗어날 때 카메라가 뒤로 물러나고, 그 뒤 다시 어깨 너머로 돌아오는 데 걸리는 시간. Cinematic의 카메라는 카메라 탭에 각자의 시간이 있습니다."
L["Turn to NPCs you talk to"] = "대화하는 NPC 쪽으로 돌기"
L["As you talk to an NPC (or a vendor, banker, trainer or flight master), the camera turns slowly to bring them toward the middle of the screen, and goes back as you close the window: a slow glide in Cinematic's quest bubble, at the game's own pace in the game's windows. It steps aside while Cinematic's quest or chat camera moves the view."] = "NPC(또는 상인, 은행원, 기술 전문가, 비행 조련사)와 대화하면 카메라가 천천히 돌아 그들을 화면 가운데 쪽으로 데려오고, 창을 닫으면 돌아갑니다: Cinematic의 퀘스트 말풍선에서는 느린 미끄러짐, 게임 창에서는 게임 자체의 속도로. Cinematic의 퀘스트 카메라나 대화 카메라가 시점을 움직이는 동안에는 물러납니다."
L["Turn to enemy"] = "적 쪽으로 돌기"
L["Turns to your target wherever you are, in fights too. (The other columns then have nothing to add.)"] = "어디에 있든 대상 쪽으로 돕니다, 전투 중에도. (다른 열은 더할 것이 없습니다.)"
L["As you target an enemy, the camera turns slowly toward it, and glides back at the same pace once you clear your target, pick a friendly one or it dies."] = "적을 대상으로 지정하면 카메라가 천천히 그쪽으로 돌고, 대상을 해제하거나 우호 대상을 고르거나 그 적이 죽으면 같은 속도로 돌아옵니다."
L["Where the camera turns to your target, and whether in fights. Unticked here, it glides back over your shoulder, and turns again once you're somewhere ticked."] = "카메라가 대상 쪽으로 도는 곳과 전투 중 여부. 여기서 체크 해제하면 어깨 너머로 돌아오고, 체크된 곳에 오면 다시 돕니다."
L["Enemy turn takes"] = "적 회전 시간"
L["How long the turn toward your target takes, and the glide back."] = "대상 쪽으로 도는 데 걸리는 시간과 돌아오는 시간."
L["NPC turn takes"] = "NPC 회전 시간"
L["How long the turn toward who you talk to takes as the window opens."] = "창이 열릴 때 대화 상대 쪽으로 도는 데 걸리는 시간."
L["NPC turn back takes"] = "NPC 복귀 시간"
L["How long the glide back over your shoulder takes as you close the window. Going from one window to the next with them (a quest's text, the next quest) it stays on them."] = "창을 닫을 때 어깨 너머로 돌아오는 데 걸리는 시간. 그들과 한 창에서 다음 창으로 넘어가면(퀘스트 내용, 다음 퀘스트) 그들을 계속 봅니다."
L["Look at them for"] = "바라보는 시간"
L["At 0 the camera stays on them till you close the window. Set a time and it glides back on its own after that long, the window still open."] = "0이면 창을 닫을 때까지 카메라가 그들을 봅니다. 시간을 정하면 창이 열려 있어도 그 시간이 지나면 저절로 돌아옵니다."
L["The frames ticked below slide over to where you are on the screen, and glide back as the camera goes behind you. Edit Mode still places them: this moves them from there."] = "아래에 체크한 프레임이 화면에서 내가 있는 곳으로 미끄러지고, 카메라가 뒤로 물러나면 돌아옵니다. 편집 모드가 여전히 위치를 정하며, 이것은 거기서부터 옮깁니다."
L["Frames follow the turn"] = "프레임이 회전을 따라옴"
L["Your cast bar and Personal Resource Display slide along with you as the camera turns toward your target. The game doesn't say how far it turned, so this works it out from where you clicked: picked with Tab, they join in once your mouse passes over it. Experimental: dragging the camera with the mouse loses it till you pick a target again."] = "카메라가 대상 쪽으로 돌 때 시전 바와 개인 자원 표시가 함께 미끄러집니다. 게임이 얼마나 돌았는지 알려 주지 않아서 클릭한 위치로 계산합니다: Tab으로 고르면 마우스가 그 위를 지나갈 때 합류합니다. 실험적: 마우스로 카메라를 끌면 다시 대상을 고를 때까지 놓칩니다."
L["Slides with you. A frame placed on it in Edit Mode slides along with it, ticked or not."] = "함께 미끄러집니다. 편집 모드에서 이 위에 놓은 프레임은 체크 여부와 상관없이 함께 미끄러집니다."
L["Swing timers"] = "공격 타이머"
L["Cooldowns: essential"] = "재사용 대기시간: 핵심"
L["Cooldowns: utility"] = "재사용 대기시간: 보조"
L["Tracked buffs: icons"] = "추적 강화 효과: 아이콘"
L["Tracked buffs: bars"] = "추적 강화 효과: 바"
L["Spell alerts"] = "주문 경보"
L["Height (all)"] = "높이 (전체)"
L["Raises (or lowers) all the ticked frames together while the camera is over your shoulder; they glide back down as it goes behind you. Each one's own slider, on its row, adds to this."] = "카메라가 어깨 너머에 있는 동안 체크한 모든 프레임을 함께 올리거나 내립니다. 카메라가 뒤로 물러나면 다시 내려옵니다. 각 줄에 있는 개별 슬라이더가 여기에 더해집니다."
L["This frame's own height, on top of Height (all). A frame placed on it in Edit Mode moves with it."] = "높이 (전체) 위에 더해지는 이 프레임 자체의 높이. 편집 모드에서 이 위에 놓은 프레임은 함께 움직입니다."
L["How many seconds the camera takes to go back behind you as this camera starts, and back over your shoulder as it ends. Leave it empty for the usual %s seconds."] = "이 카메라가 시작될 때 카메라가 뒤로 물러나고, 끝날 때 다시 어깨 너머로 돌아오는 데 걸리는 초. 비워 두면 보통의 %s초입니다."
L["Transition"] = "전환"
L["Allow the Shoulder Cam"] = "어깨 카메라 허용"
L["Unticked, the camera goes back behind you while that camera plays and comes back over your shoulder as it ends. Ticked, it stays: you keep your spot on the screen as the camera turns round you."] = "체크 해제 시 그 카메라가 재생되는 동안 카메라가 뒤로 물러났다가 끝나면 어깨 너머로 돌아옵니다. 체크 시 유지됩니다: 카메라가 주위를 도는 동안 화면 위치를 지킵니다."
L["Keeps the camera over your shoulder while this camera plays."] = "이 카메라가 재생되는 동안 카메라를 어깨 너머에 유지합니다."
L["Your Hearthstone and teleports."] = "귀환석과 순간이동."
L["Flight paths and their fly-bys. The flight's mount pushes you further aside than your spot, and the frames that follow you don't know by how much yet."] = "비행 경로와 그 근접 비행. 비행 탈것은 내 위치보다 더 옆으로 밀어내며, 따라오는 프레임은 아직 얼마나인지 모릅니다."
L["While you're dead, until you release."] = "죽어 있는 동안, 영혼을 해방할 때까지."
L["Walk camera"] = "걷기 카메라"
L["While you talk to a quest giver."] = "퀘스트를 주는 NPC와 대화하는 동안."
L["Your own cameras"] = "내 카메라"
L["Your scripts and shots, and cameras started from the camera wheel or a key."] = "내 스크립트와 샷, 그리고 카메라 휠이나 키로 시작한 카메라."
L["Not supported at the moment"] = "현재 지원되지 않음"
L["The Shoulder Cam doesn't work with the gamepad UI yet. While it's on, the game keeps your character in the middle of the screen, so the Shoulder Cam waits behind you and comes back by itself when you turn the gamepad UI off (Options > Gamepad (Beta) > Enable Gamepad UI)."] = "어깨 카메라는 아직 게임패드 UI와 함께 작동하지 않습니다. 켜져 있는 동안 게임이 캐릭터를 화면 가운데에 고정하므로, 어깨 카메라는 뒤에서 기다리다가 게임패드 UI를 끄면 저절로 돌아옵니다 (설정 > 게임패드 (베타) > 게임패드 UI 사용)."
L["Calibrating my camera, please ignore this line for a moment: I'm measuring where my character sits on the screen as the camera moves over my shoulder. Thanks for your patience!"] = "카메라를 보정하는 중이니 잠시 이 줄은 무시해 주세요: 카메라가 어깨 너머로 갈 때 화면에서 제 캐릭터가 어디에 있는지 재고 있어요. 기다려 주셔서 감사합니다!"
L["On foot"] = "도보"
L["Form %s"] = "형상 %s"
L["Calibration stopped"] = "보정 중지됨"
L["Calibration: not enough readings"] = "보정: 측정값이 부족합니다"
L["Try again somewhere open and flat."] = "탁 트이고 평평한 곳에서 다시 시도하세요."
L["Saved, and in use now. Share it from the Calibrate tab."] = "저장했고 지금 사용 중입니다. 보정 탭에서 공유하세요."
L["The readings disagree (%.2f apart): try again somewhere open and flat."] = "측정값이 맞지 않습니다 (%.2f 차이): 탁 트이고 평평한 곳에서 다시 시도하세요."
L["Calibrating: step %d of %d"] = "보정 중: %d / %d 단계"
L["Stand still and leave the camera alone."] = "가만히 서서 카메라를 건드리지 마세요."
L["Say it again and go on"] = "다시 말하고 계속"
L["The bubble's gone: click the button below to go on."] = "말풍선이 사라졌습니다: 아래 버튼을 눌러 계속하세요."
L["A fight started."] = "전투가 시작되었습니다."
L["You picked a target: clear it (Esc) and start again."] = "대상을 골랐습니다: 해제하고(Esc) 다시 시작하세요."
L["It's already running."] = "이미 진행 중입니다."
L["Get off your mount first."] = "먼저 탈것에서 내리세요."
L["Clear your target first (Esc)."] = "먼저 대상을 해제하세요 (Esc)."
L["This client can't read chat bubbles."] = "이 클라이언트는 대화 말풍선을 읽을 수 없습니다."
L["Not in a dungeon, raid or battleground."] = "던전, 공격대, 전장에서는 안 됩니다."
L["Stopped."] = "중지됨."
L["Calibrate the Shoulder Cam for %s?\n\nIt says a line in /say a few times (everyone near you sees it), so somewhere quiet is best. Stand still on open, flat ground and leave the camera alone for about 10 seconds."] = "%s의 어깨 카메라를 보정할까요?\n\n/말하기로 한 줄을 몇 번 말하므로(근처의 모두가 봅니다) 조용한 곳이 좋습니다. 탁 트이고 평평한 땅에 가만히 서서 약 10초 동안 카메라를 건드리지 마세요."
L["Yes"] = "예"
L["No"] = "아니요"
L["If you sit too far to the side or too close to the middle in a form (or on foot), calibrate it. Share sends us your numbers so everyone gets them."] = "형상(또는 도보)에서 너무 옆에 있거나 너무 가운데 가깝다면 보정하세요. 공유하면 수치가 저희에게 전송되어 모두가 받게 됩니다."
L["Measures the race, sex and form you are now. Stand still on open, flat ground, nothing targeted, and leave the camera alone for about 10 seconds. It says a line in /say a few times."] = "지금의 종족, 성별, 형상을 측정합니다. 탁 트이고 평평한 땅에 대상 없이 가만히 서서 약 10초 동안 카메라를 건드리지 마세요. /말하기로 한 줄을 몇 번 말합니다."
L["Your Shoulder Cam measurements"] = "내 어깨 카메라 측정값"
L["Your measurements on one line: copy it and paste it to us on Discord or GitHub."] = "한 줄로 된 내 측정값: 복사해서 Discord나 GitHub에 붙여 넣어 주세요."
L["Your measurements"] = "내 측정값"
L["Character"] = "캐릭터"
L["Form"] = "형상"
L["Date"] = "날짜"
L["None yet: calibrate to add one."] = "아직 없음: 보정해서 추가하세요."
L["Stops using this measurement: the built-in size comes back."] = "이 측정값 사용을 멈춥니다: 기본 크기가 돌아옵니다."
L["You now: |cffffffff%s|r, size |cffffffff%.2f|r |cff9d9d9d(%s)|r"] = "지금: |cffffffff%s|r, 크기 |cffffffff%.2f|r |cff9d9d9d(%s)|r"
L["Good"] = "좋음"
L["Not used"] = "사용 안 함"
L["Cinema, over your shoulder. The camera sits over your shoulder with you to one side of the screen, and your resources, cast bar and Cooldown Manager sit under you and slide along with you. Fights bring up your personal resource display instead of your portrait. Everything else is Cinema's: as little UI as possible, every camera, Vision and all the atmosphere."] = "Cinema를 어깨 너머로. 카메라가 어깨 너머에 있고 나는 화면 한쪽에 있으며, 자원, 시전 바, 재사용 대기시간 관리자가 내 아래에서 함께 미끄러집니다. 전투에서는 초상화 대신 개인 자원 표시가 나옵니다. 나머지는 모두 Cinema와 같습니다: 최소한의 UI, 모든 카메라, 비전, 그리고 모든 분위기."

-- Shoulder Cam: the welcome level, its test and Customize choices (ProfileChoices.lua, Welcome.lua, ShowMe.lua)
L["Almost always, over your shoulder"] = "거의 항상, 어깨 너머로"
L["As little UI as possible; your resources, not your portrait, in fights"] = "최소한의 UI; 전투 중에는 초상화 대신 자원"
L["Your resources at the bottom middle, everything hung on them"] = "자원을 화면 아래 가운데에, 모든 것을 그 위에 연결"
L["Cinema, with the camera over your shoulder."] = "어깨 너머 카메라를 곁들인 Cinema."
L["It uses one of Blizzard's experimental camera settings: picking it or its test agrees to that. Turn the Shoulder Cam off and your own camera settings come back."] = "Blizzard의 실험적 카메라 설정 중 하나를 사용합니다: 이것을 고르거나 테스트하면 동의한 것으로 봅니다. 어깨 카메라를 끄면 원래 카메라 설정이 돌아옵니다."
L["The camera moves over your shoulder, with you to one side of the screen. This glides in, swaps shoulders once and glides back. It uses one of Blizzard's experimental camera settings: trying it agrees to that, and your own camera settings come back after."] = "카메라가 어깨 너머로 이동하고 나는 화면 한쪽에 있습니다. 부드럽게 들어와 어깨를 한 번 바꾸고 돌아갑니다. Blizzard의 실험적 카메라 설정 중 하나를 사용합니다: 테스트하면 동의한 것으로 보며, 끝나면 원래 카메라 설정이 돌아옵니다."
L["Another addon has the shoulder camera (DynamicCam): the Shoulder Cam stands aside for it."] = "다른 애드온이 어깨 카메라를 사용 중입니다 (DynamicCam): 어깨 카메라가 물러납니다."
L["Over your shoulder outdoors, off your mount and out of dungeons and raids."] = "야외에서, 탈것에 타지 않고, 던전과 공격대 밖에서 어깨 너머로."

-- Shoulder Cam: the welcome level, its test and Customize choices (ProfileChoices.lua, Welcome.lua, ShowMe.lua)
L["Cinematic leaves your Edit Mode layout as it is; your personal resource display on, up in fights"] = "Cinematic이 편집 모드 레이아웃을 그대로 둡니다; 개인 자원 표시는 켜지고 전투 중에 표시됩니다"

-- Camera hub: the Special Cams section (Options.lua HUBS)
L["Special Cams"] = "특수 카메라"

-- Shoulder Cam page: Clear target on Esc while interacting with an NPC
L["Clear target on Esc while interacting with an NPC"] = "NPC와 상호작용 중 Esc로 대상 해제"
L["With a talk window open, Escape clears your target and closes the window in the same press, the camera gliding back off them. Off: Escape only closes it, and your target stays."] = "대화 창이 열려 있을 때 Esc 한 번으로 대상을 해제하고 창을 닫으며, 카메라는 그들에게서 부드럽게 돌아옵니다. 꺼짐: Esc는 창만 닫고 대상은 그대로입니다."

-- ===== Added for the 2026-11-20 full release (every string the code had that this file lacked) =====

-- FrameGuess.lua
L["%s holds frames that fade with a row on the HUD page: set them there."] = "%s에는 HUD 페이지의 줄에 따라 흐려지는 창이 있습니다: 거기서 설정하세요."

-- Core.lua
L["Quests and chat"] = "퀘스트와 대화"
L["Scene key %d"] = "장면 키 %d"
L["Hide Cursor till moves"] = "움직일 때까지 커서 숨기기"
L["Toggle settings"] = "설정 열기/닫기"
L["Keyboard map (hold, or tap to keep it up)"] = "키보드 배치도 (누르고 있기, 또는 살짝 눌러 띄워 두기)"
L["Exit CineMode: %s is ticked."] = "CineMode 종료: %s에 체크되어 있습니다."
L["Cinematic stopped itself for this session after an error. Type /cine resume to start it again."] = "오류가 나서 Cinematic이 이번 접속 동안 스스로 멈췄습니다. /cine resume을 입력하면 다시 시작합니다."
L["Cinematic is switched off. Type /cine on to turn it back on."] = "Cinematic이 꺼져 있습니다. /cine on을 입력하면 다시 켭니다."
L["You haven't picked a profile yet: finish the welcome window first."] = "아직 프로필을 고르지 않았습니다: 먼저 환영 창을 마치세요."
L["Start in CineMode is unticked, so CineMode only comes on while one of your camera scenes runs."] = "'CineMode로 시작'이 해제되어 있어서, 카메라 장면이 도는 동안에만 CineMode가 켜집니다."
L["You turned it off for a while from the minimap button's menu."] = "미니맵 버튼 메뉴에서 잠시 꺼 두었습니다."
L["CineMode is set to stay off here."] = "이곳에서는 CineMode가 꺼져 있도록 설정되어 있습니다."
L["CineMode is set to stay off in your group."] = "지금 파티에서는 CineMode가 꺼져 있도록 설정되어 있습니다."
L["In a raid group"] = "공격대에 있을 때"
L["In a party"] = "파티에 있을 때"
L["You're moving."] = "움직이는 중입니다."
L["When moving"] = "움직일 때"
L["You just moved: CineMode comes back once you've stood still, or kept going, for a moment."] = "방금 움직였습니다: 잠시 가만히 있거나 계속 움직이면 CineMode가 돌아옵니다."
L["CineMode comes back in %d sec (Back into CineMode after)."] = "%d초 뒤에 CineMode가 돌아옵니다 (CineMode로 돌아가기까지)."
L["You're in combat."] = "전투 중입니다."
L["A fight just ended: CineMode comes back once the Calm Timer runs out."] = "방금 전투가 끝났습니다: 진정 타이머가 끝나면 CineMode가 돌아옵니다."
L["You're dead: the UI comes back until you release or get up."] = "죽은 상태입니다: 영혼을 놓거나 되살아날 때까지 UI가 보입니다."
L["You're casting."] = "시전 중입니다."
L["You're holding something on the cursor."] = "커서에 무언가를 들고 있습니다."
L["A game window is open."] = "게임 창이 열려 있습니다."
L["An NPC's window is open."] = "NPC 창이 열려 있습니다."
L["Something just brought the UI back (a fight, a cast or a window)."] = "방금 무언가가 UI를 다시 불러왔습니다 (전투, 시전 또는 창)."
L["Something went wrong: type /cine log and send it to us."] = "문제가 생겼습니다: /cine log를 입력해서 저희에게 보내 주세요."
L["The game's floating text stays hidden until you fully restart the game."] = "게임을 완전히 다시 시작할 때까지 게임의 전투 문자가 숨겨진 채로 있습니다."
L["Turn off and reload"] = "끄고 다시 불러오기"
L["Cinematic is off (/cine on turns it on)"] = "Cinematic이 꺼져 있습니다 (/cine on으로 켭니다)"
L["CineMode on"] = "CineMode 켜짐"
L["CineMode off"] = "CineMode 꺼짐"
L["the death camera is off: turn it on for Death on the Scenes page"] = "죽음 카메라가 꺼져 있습니다: 장면 페이지에서 죽음에 켜세요"
L["the AFK camera's rotation is off: see its Scripts page"] = "자리 비움 카메라의 회전이 꺼져 있습니다: 스크립트 페이지를 보세요"

-- Skin.lua
L["Pop out to move the window anywhere, or dock it back by the settings."] = "떼어 내면 창을 아무 데나 옮길 수 있고, 다시 설정 옆에 붙일 수도 있습니다."

-- UI/GridRows.lua
L["Dead target"] = "죽은 대상"
L["On a flight path"] = "비행 경로 이용 중"
L["CQL is the words a rule is written in, joined with AND, OR and NOT."] = "CQL은 규칙을 쓰는 단어들로, AND, OR, NOT으로 잇습니다."
L["Adds \"%s\": true for a tooltip of this kind."] = "\"%s\" 추가: 이런 종류의 툴팁이면 참입니다."
L["Adds \"%s\"; a green dot means it's true where you are now."] = "\"%s\" 추가: 초록 점은 지금 있는 곳에서 참이라는 뜻입니다."
L["Out of fights only."] = "전투 밖에서만."
L["The rule isn't finished; finish it or press Escape to undo."] = "규칙이 끝나지 않았습니다: 마저 쓰거나 Esc를 눌러 되돌리세요."
L["Makes this row show whenever another row of its table does, instead of a rule."] = "규칙 대신, 같은 표의 다른 줄이 보일 때마다 이 줄도 보이게 합니다."
L["Green: it would show in CineMode now; gray: hidden; none: rule not finished."] = "초록: 지금 CineMode에서 보임, 회색: 숨김, 없음: 규칙이 끝나지 않음."
L["Follows %s and shows when it does."] = "%s을(를) 따라가서 그것이 보일 때 보입니다."
L["Opens the rule editor for more options than the dropdowns have."] = "드롭다운보다 많은 옵션이 있는 규칙 편집기를 엽니다."
L["Can't: %s. Open the rule to change it."] = "불가: %s. 바꾸려면 규칙을 여세요."
L["Set on the Style Overrides tab; click to open it."] = "스타일 재정의 탭에서 설정합니다. 클릭하면 열립니다."
L["On out of fights, once the Calm Timer after one has run out."] = "전투 밖에서, 전투 후 진정 타이머가 끝나면 켜집니다."
L["Shows it whenever its frame shows, even in CineMode."] = "CineMode에서도 그 창이 보일 때마다 표시합니다."
L["Shows it all through CineMode instead of hiding it."] = "숨기지 않고 CineMode 내내 표시합니다."
L["Your choice in the game's options; Off shows nothing here."] = "게임 옵션에서 고른 값입니다. 꺼짐이면 여기에 아무것도 표시하지 않습니다."
L["Click to show or hide this section."] = "클릭하면 이 섹션을 펼치거나 접습니다."

