-- Camera/ShoulderCam.lua
L["Toggle Shoulder Cam"] = "어깨 카메라 켜기/끄기"
L["Moves the camera over your shoulder, using one of Blizzard's experimental camera settings."] = "블리자드의 실험적 카메라 설정 하나를 써서 카메라를 어깨 너머로 옮깁니다."
L["Why the Shoulder Cam pauses while the gamepad UI is on."] = "게임패드 UI가 켜져 있는 동안 어깨 카메라가 멈추는 이유."
L["Puts the camera over your left shoulder instead of your right."] = "카메라를 오른쪽 대신 왼쪽 어깨 너머에 둡니다."
L["How far from the middle of the screen you sit."] = "캐릭터가 화면 가운데에서 얼마나 떨어져 있을지."
L["Spot zoomed out"] = "축소했을 때 위치"
L["How far from the middle you sit when zoomed out. Lower than Spot on screen keeps the camera off walls, which only catch it zoomed out."] = "축소했을 때 캐릭터가 가운데에서 얼마나 떨어져 있을지. 화면 위치보다 낮게 하면 카메라가 벽에 걸리지 않습니다 (벽은 축소했을 때만 걸립니다)."
L["Zoomed out at"] = "축소 기준 거리"
L["How far away the camera is when you sit at Spot zoomed out. From 5 yards out to here your spot moves from Spot on screen to it."] = "'축소했을 때 위치'에 도달하는 카메라 거리. 5미터부터 여기까지 위치가 화면 위치에서 그쪽으로 옮겨 갑니다."
L["How long the camera takes to swap to your other shoulder."] = "카메라가 반대쪽 어깨로 넘어가는 데 걸리는 시간."
L["How long the camera takes to go back over your shoulder after you stop targeting yourself."] = "자신을 대상으로 잡지 않게 된 뒤 카메라가 어깨 너머로 돌아가는 데 걸리는 시간."
L["How long the camera takes to move behind you when the Shoulder Cam pauses, and back."] = "어깨 카메라가 멈출 때 카메라가 뒤로 갔다가 다시 돌아오는 데 걸리는 시간."
L["How long the Shoulder Cam waits before coming back over your shoulder once it can again: you step outside or get off your mount. Going back in or getting on again in that time starts the wait over."] = "다시 가능해졌을 때(밖으로 나가거나 탈것에서 내릴 때) 어깨 카메라가 어깨 너머로 돌아오기 전에 기다리는 시간. 그 사이 다시 들어가거나 탈것에 오르면 처음부터 다시 기다립니다."
L["Turns to who you talk to wherever you are. (The other columns then have nothing to add.)"] = "어디에 있든 대화 상대 쪽으로 돕니다. (그러면 다른 열은 더할 것이 없습니다.)"
L["The camera turns toward the NPC you talk to while their window is open."] = "NPC 창이 열려 있는 동안 카메라가 대화하는 NPC 쪽으로 돕니다."
L["Where the camera turns toward who you talk to."] = "카메라가 대화 상대 쪽으로 도는 곳."
L["Escape clears your target and closes an NPC's window in one press."] = "Esc를 한 번 누르면 대상을 해제하고 NPC 창을 닫습니다."
L["Multi Quest fix"] = "다중 퀘스트 수정"
L["Dev test: at a quest giver with more quests, Accept clears your target first."] = "개발 시험: 퀘스트가 더 있는 퀘스트 NPC에서 수락하면 먼저 대상을 해제합니다."
L["How long the camera takes to glide back over your shoulder after you close the window."] = "창을 닫은 뒤 카메라가 어깨 너머로 부드럽게 돌아가는 데 걸리는 시간."
L["Turns to your target everywhere, in fights too."] = "전투 중에도 어디서나 대상 쪽으로 돕니다."
L["The camera turns slowly toward the enemy you target."] = "카메라가 대상으로 잡은 적 쪽으로 천천히 돕니다."
L["Where the camera turns toward your target."] = "카메라가 대상 쪽으로 도는 곳."
L["How long the turn toward your target takes."] = "대상 쪽으로 도는 데 걸리는 시간."
L["Enemy turn back takes"] = "적에서 돌아오는 시간"
L["How long the camera takes to glide back after you clear your target."] = "대상을 해제한 뒤 카메라가 부드럽게 돌아가는 데 걸리는 시간."
L["Glide back when you clear your target"] = "대상 해제 시 부드럽게 돌아가기"
L["Glides back instead of snapping when you clear your target, briefly using soft enemy targeting."] = "대상을 해제할 때 확 튀지 않고 부드럽게 돌아갑니다. 잠깐 적 자동 대상 지정을 씁니다."
L["The ticked frames slide over to where you are on the screen."] = "체크한 창이 화면에서 캐릭터가 있는 쪽으로 미끄러져 갑니다."
L["Your cast bar and Personal Resource Display slide along as the camera turns to your target."] = "카메라가 대상 쪽으로 돌 때 시전 바와 개인 자원 표시도 함께 미끄러집니다."
L["Slides with you."] = "함께 미끄러집니다."
L["Loss of control"] = "제어 불가"
L["Floating combat text"] = "전투 문자"
L["Raises or lowers all the ticked frames while the camera is over your shoulder."] = "카메라가 어깨 너머에 있는 동안 체크한 창을 모두 올리거나 내립니다."
L["How far the frames slide; adjust it if they land short of you or past you."] = "창이 미끄러지는 거리. 캐릭터에 못 미치거나 지나치면 조절하세요."
L["This frame's own height, added to Height (all)."] = "높이 (전체)에 더해지는 이 창만의 높이."
L["Seconds the camera takes to move behind you for this camera; empty uses %s."] = "이 카메라를 위해 카메라가 뒤로 가는 데 걸리는 초. 비우면 %s 사용."
L["Flight paths and their fly-bys."] = "비행 경로와 플라이바이."

-- Camera/ShoulderCalibrate.lua
L["Mount %s"] = "탈것 %s"
L["Mount"] = "탈것"
L["Land first: stand still on the ground."] = "먼저 착륙하세요: 땅에 가만히 서 있으세요."
L["This mount can't be read here."] = "여기서는 이 탈것을 읽을 수 없습니다."
L["Measures your current form or mount; stand still for 10 seconds while it says a line in /say."] = "현재 변신 형태나 탈것을 측정합니다. /say로 한 줄 말하는 동안 10초간 가만히 서 있으세요."

-- Camera/SkyrideCam.lua
L["While you skyride, the camera zooms out and gives each ability its own shot."] = "용 조련술로 나는 동안 카메라가 멀어지고 능력마다 고유한 연출을 보여 줍니다."
L["Zooms the camera out and moves it with your abilities while you skyride."] = "용 조련술로 나는 동안 카메라를 멀리 빼고 능력에 맞춰 움직입니다."
L["Wherever you skyride. (The other columns then have nothing to add.)"] = "용 조련술로 나는 곳 어디서나. (그러면 다른 열은 더할 것이 없습니다.)"
L["%d degrees"] = "%d도"
L["How long the camera stays there before going back."] = "카메라가 돌아가기 전에 그 자리에 머무는 시간."
L["Take off"] = "이륙"
L["Zoom out"] = "축소"
L["Zooms the camera out as you take to the air."] = "공중으로 날아오를 때 카메라를 멀리 뺍니다."
L["Zoom out to"] = "축소 거리"
L["How far out the camera goes while you skyride."] = "용 조련술로 나는 동안 카메라가 멀어지는 거리."
L["Over"] = "걸리는 시간"
L["How long you're in the air before the camera zooms out, so a hop doesn't start it."] = "카메라가 멀어지기 전에 공중에 있어야 하는 시간. 살짝 뛰는 것으로는 시작하지 않게 합니다."
L["Surge Forward"] = "앞으로 쇄도"
L["Surge Forward pulls the camera out for a moment, then lets it drift back."] = "앞으로 쇄도는 카메라를 잠깐 멀리 뺐다가 천천히 돌려놓습니다."
L["By"] = "만큼"
L["How far past your cruise distance (Take off's)."] = "순항 거리(이륙의 거리)보다 더 멀어지는 정도."
L["Hold"] = "유지"
L["Back over"] = "돌아오는 시간"
L["Skyward Ascent"] = "하늘로 상승"
L["Tilt up"] = "위로 기울이기"
L["Skyward Ascent tilts the camera up as you climb, then back."] = "하늘로 상승은 올라갈 때 카메라를 위로 기울였다가 되돌립니다."
L["Whirling Surge"] = "소용돌이 쇄도"
L["Whirling Surge throws the camera out fast, then lets it catch up slowly."] = "소용돌이 쇄도는 카메라를 빠르게 멀리 던졌다가 천천히 따라오게 합니다."
L["To"] = "까지"
L["0.5: a snap, as quick as the game's zoom goes."] = "0.5: 게임 확대/축소만큼 빠르게 휙."
L["Aerial Halt"] = "공중 정지"
L["Swing around and zoom in"] = "돌아가며 확대"
L["Aerial Halt swings the camera around for a close shot of you hovering."] = "공중 정지는 카메라를 돌려 떠 있는 캐릭터를 가까이 비춥니다."
L["Zoom in to"] = "확대 거리"
L["How close the camera comes in; 0 keeps its distance."] = "카메라가 다가오는 거리. 0이면 거리를 그대로 둡니다."
L["Second Wind"] = "재기의 바람"
L["Zoom in and back"] = "확대 후 복귀"
L["Each way."] = "한 방향당."
L["Climbing"] = "상승"
L["The camera tilts up with you as you climb steeply."] = "가파르게 올라갈 때 카메라가 함께 위로 기울어집니다."
L["Up to"] = "최대"
L["Diving"] = "급강하"
L["Tilt down"] = "아래로 기울이기"
L["The camera tilts down toward where you dive."] = "급강하하는 쪽으로 카메라가 아래로 기울어집니다."
L["Swing into the turn"] = "선회 방향으로 돌기"
L["The camera swings toward your turn when you turn hard with the keys."] = "키로 급하게 선회할 때 카메라가 선회 방향으로 돕니다."
L["Follow your turns"] = "선회 따라가기"
L["The camera holds its direction as you turn, then glides back behind you."] = "선회하는 동안 카메라가 방향을 유지하다가 부드럽게 뒤로 돌아옵니다."
L["Glide back after"] = "돌아오기 전 대기"
L["How long after you stop turning the camera starts gliding back behind you."] = "선회를 멈춘 뒤 카메라가 뒤로 돌아오기 시작할 때까지의 시간."
L["Fall behind at most"] = "최대 뒤처짐"
L["The furthest you can turn away before the camera turns with you."] = "카메라가 따라 돌기 전까지 돌 수 있는 최대 각도."
L["Zoom back to your distance"] = "원래 거리로 복귀"
L["Landing brings the camera back to the distance you took off at."] = "착륙하면 카메라가 이륙할 때의 거리로 돌아옵니다."
L["Back to your distance over"] = "원래 거리 복귀 시간"
L["How long the camera takes to come back to your distance after you land."] = "착륙 후 카메라가 원래 거리로 돌아오는 데 걸리는 시간."
L["Start after landing"] = "착륙 후 시작"
L["How long you stay landed before the camera starts coming back."] = "카메라가 돌아오기 시작하기 전에 착륙해 있어야 하는 시간."
L["The fastest the camera moves; quicker moments take longer instead."] = "카메라의 최대 속도. 더 빠른 순간은 대신 시간이 더 걸립니다."
L["Blend"] = "부드럽게 잇기"
L["Fastest turn"] = "최대 회전 속도"
L["%d degrees a second"] = "초당 %d도"
L["Fastest tilt"] = "최대 기울기 속도"
L["Fastest zoom"] = "최대 확대/축소 속도"
L["%d yards a second"] = "초당 %d미터"
L["Blend into the next move"] = "다음 동작으로 잇기"
L["Slides one move smoothly into the next; 0 stops first."] = "한 동작을 다음 동작으로 부드럽게 잇습니다. 0이면 먼저 멈춥니다."
L["CineMode"] = "CineMode"
L["CineMode while skyriding"] = "용 조련술 중 CineMode"
L["Brings CineMode on while you skyride, if Start in CineMode is off."] = "'CineMode로 시작'이 꺼져 있으면 용 조련술로 나는 동안 CineMode를 켭니다."

-- Camera/TriggerLibrary.lua
L["The cast starts"] = "시전 시작"
L["The cast succeeds"] = "시전 성공"
L["You gain it"] = "효과를 얻음"
L["It fades"] = "효과가 사라짐"
