L["The window closes"] = "창이 닫힘"
L["held back"] = "보류됨"
L["lost"] = "밀림"

-- Camera/CustomTriggers.lua
L["You rest the cursor on a campfire"] = "모닥불에 커서를 올려 둠"
L["%s. Scene: %s, camera: %s"] = "%s. 장면: %s, 카메라: %s"
L["Fire now"] = "지금 발동"
L["Started"] = "시작됨"
L["%s started"] = "%s 시작됨"
L["Its Starts or Scenes tab is off"] = "시작 또는 장면 탭이 꺼져 있음"
L["Cameras are held to CineMode (CineMode page, Camera tab)"] = "카메라는 CineMode에서만 작동하게 되어 있음 (CineMode 페이지, 카메라 탭)"
L["The cast ended"] = "시전 끝남"
L["It ended"] = "끝남"
L["Another emote"] = "다른 감정 표현"
L["You moved"] = "움직임"
L["Its time ran out"] = "시간이 다 됨"
L["(a deleted trigger)"] = "(삭제된 발동 조건)"
L["Its key was pressed again"] = "키를 다시 누름"
L["no scene uses %s yet: give it a trigger on the Triggers page"] = "아직 %s을(를) 쓰는 장면이 없습니다: 발동 조건 페이지에서 발동 조건을 지정하세요"
L["Stopped on the Triggers page"] = "발동 조건 페이지에서 중지함"
L["Fire now. Nothing uses it yet"] = "지금 발동. 아직 쓰는 곳 없음"

-- Camera/Shots.lua
L["How long each move takes; longer is slower and smoother."] = "각 동작에 걸리는 시간. 길수록 느리고 부드럽습니다."
L["How fast the camera drifts between moves; 0 turns it off."] = "동작 사이에 카메라가 흘러가는 속도. 0이면 끕니다."

-- Camera/CameraTriggerEditor.lua
L["(ours)"] = "(기본 제공)"
L["New trigger..."] = "새 발동 조건..."
L["Opens this trigger's page."] = "이 발동 조건의 페이지를 엽니다."
L["Take this trigger off the scene (it then starts nothing), or put it back."] = "이 발동 조건을 장면에서 빼거나(그러면 아무것도 시작하지 않음) 다시 넣습니다."
L["A trigger that starts this scene; any one of them starts it."] = "이 장면을 시작하는 발동 조건. 어느 하나만 맞아도 시작합니다."
L["Opens this trigger's page; changes there apply to every scene using it."] = "이 발동 조건의 페이지를 엽니다. 거기서 바꾼 내용은 이를 쓰는 모든 장면에 적용됩니다."
L["Take this trigger off the scene (it stays on the Triggers page)."] = "이 발동 조건을 장면에서 뺍니다 (발동 조건 페이지에는 남습니다)."
L["Text a friend can import to add this scene."] = "친구가 이 장면을 추가할 때 가져올 수 있는 텍스트."
L["Your own name for it; leave empty to show what starts it."] = "직접 붙이는 이름. 비워 두면 무엇이 시작하는지 표시합니다."
L["Brings CineMode on while its camera runs, if Start in CineMode is off."] = "'CineMode로 시작'이 꺼져 있으면 이 카메라가 도는 동안 CineMode를 켭니다."
L["Adds it to the rows below."] = "아래 줄에 추가합니다."

-- Camera/TriggersPage.lua
L["Every trigger, ours and yours: open one to change it."] = "기본 제공과 내가 만든 모든 발동 조건: 열어서 바꾸세요."
L["Priority"] = "우선순위"
L["The order they win in when two are on at once."] = "둘이 동시에 켜질 때 이기는 순서."
L["Log"] = "기록"
L["What fired, what was held back and why, this session."] = "이번 접속에서 무엇이 발동했고, 무엇이 보류됐으며, 그 이유."
L["Lets your triggers fire, and ours go by your priorities and settings."] = "내 발동 조건이 발동하고, 기본 제공 발동 조건은 내 우선순위와 설정을 따르게 합니다."
L["Everything that can start a scene, in one list."] = "장면을 시작할 수 있는 모든 것을 한 목록에."
L["Ours"] = "기본 제공"
L["Unused"] = "미사용"
L["On now"] = "지금 켜짐"
L["Which triggers to list."] = "목록에 보일 발동 조건."
L["By group"] = "그룹별"
L["By kind"] = "종류별"
L["How the list is grouped."] = "목록을 묶는 방식."
L["+ New trigger"] = "+ 새 발동 조건"
L["Makes a trigger of your own and opens its page."] = "나만의 발동 조건을 만들고 그 페이지를 엽니다."
L["Trigger"] = "발동 조건"
L["Starts when"] = "시작 조건"
L["Scene"] = "장면"
L["Its camera takes turns by its own rules for now."] = "지금은 이 카메라가 자체 규칙으로 순서를 정합니다."
L["Click to open its page."] = "클릭하면 페이지를 엽니다."
L["own"] = "자체"
L["No triggers match."] = "맞는 발동 조건이 없습니다."
L["When two triggers fire at once, the higher one in this list wins."] = "두 발동 조건이 동시에 발동하면 이 목록에서 위에 있는 것이 이깁니다."
L["Put ours back"] = "기본 순서로 되돌리기"
L["Puts our triggers back in their original places."] = "기본 제공 발동 조건을 원래 자리로 되돌립니다."
L["Higher: wins over the one above."] = "위로: 위의 것보다 우선합니다."
L["Lower: the one below wins over it."] = "아래로: 아래의 것이 우선합니다."
L["unused"] = "미사용"
L["tie"] = "동률"
L["A log of this session's triggers and why each did or didn't play."] = "이번 접속의 발동 조건 기록과 각각 재생되거나 되지 않은 이유."
L["Empty the log."] = "기록을 비웁니다."
L["Nothing yet. Do something one of your triggers watches for, or press Fire now on its page."] = "아직 없습니다. 발동 조건이 지켜보는 일을 하거나, 그 페이지에서 '지금 발동'을 누르세요."
L["Starts this trigger's scenes now, ignoring its rules; click again to stop."] = "규칙을 무시하고 이 발동 조건의 장면을 지금 시작합니다. 다시 클릭하면 멈춥니다."
L["A copy of this trigger, to change apart from it."] = "따로 바꿀 수 있는 이 발동 조건의 사본."
L["Delete the trigger %s? It comes off every scene using it."] = "%s 발동 조건을 삭제하시겠습니까? 이를 쓰는 모든 장면에서 빠집니다."
L["Its name, what starts it and its Only if rule."] = "이름, 시작 조건, '다음일 때만' 규칙."
L["What ends it: the first of its endings to happen."] = "끝내는 것: 끝 조건 중 먼저 일어나는 것."
L["Timing"] = "시간"
L["A wait before it starts, a least time, a cooldown and a chance."] = "시작 전 대기, 최소 시간, 재사용 대기시간, 확률."
L["Its priority, and the scenes it starts."] = "우선순위와 시작하는 장면."
L["Turns this tab of the trigger on or off."] = "발동 조건의 이 탭을 켜거나 끕니다."
L["Kind"] = "종류"
L["Spell name or ID"] = "주문 이름 또는 ID"
L["Buff name or ID"] = "강화 효과 이름 또는 ID"
L["Zone or subzone"] = "지역 또는 하위 지역"
L["Which"] = "대상"
L["An emote command, a spell or buff name or ID, or a zone name."] = "감정 표현 명령어, 주문이나 강화 효과 이름 또는 ID, 또는 지역 이름."
L["Which keybind; set its key on the Keybinds page."] = "어떤 단축키인지. 키는 단축키 페이지에서 지정하세요."
L["Only if"] = "다음일 때만"
L["Rule (CQL)"] = "규칙 (CQL)"
L["A rule it needs to start; empty means always, click to edit."] = "시작하는 데 필요한 규칙. 비우면 항상이며, 클릭해서 편집합니다."
L["Ends when"] = "끝 조건"
L["As its camera's code says, for now (moving ends it too)"] = "지금은 카메라 코드대로 (움직여도 끝남)"
L["It comes back"] = "다시 나타남"
L["Its key pressed again"] = "키를 다시 누름"
L["Another trigger starts"] = "다른 발동 조건 시작"
L["Nothing more (moving or another emote ends it)"] = "그 밖에 없음 (움직이거나 다른 감정 표현으로 끝남)"
L["Nothing more (moving ends it)"] = "그 밖에 없음 (움직이면 끝남)"
L["Take this ending off."] = "이 끝 조건을 뺍니다."
L["+ Add ending"] = "+ 끝 조건 추가"
L["Adds another way for it to end; the first that happens ends it."] = "끝나는 방법을 하나 더 추가합니다. 먼저 일어나는 것으로 끝납니다."
L["Keep going at least"] = "최소 지속"
L["Chance (%)"] = "확률 (%)"
L["Don't start again until it has stopped being true"] = "참이 아니게 될 때까지 다시 시작하지 않기"
L["On: it waits until its condition stops before it can start again."] = "켜면: 조건이 끝날 때까지 기다렸다가 다시 시작할 수 있습니다."
L["Lower wins when two triggers are on at once."] = "두 발동 조건이 동시에 켜지면 낮은 쪽이 이깁니다."
L["See the order"] = "순서 보기"
L["Opens the Priority tab."] = "우선순위 탭을 엽니다."
L["Used by"] = "사용하는 곳"
L["Use in..."] = "사용할 곳..."
L["Add this trigger to a scene (yours, or one of ours that runs while you stand still)."] = "이 발동 조건을 장면(내 장면, 또는 가만히 서 있을 때 도는 기본 제공 장면)에 추가합니다."
L["Scenes page"] = "장면 페이지"
L["Opens the Scenes page."] = "장면 페이지를 엽니다."
L["Its scene"] = "해당 장면"
L["A scene of its own"] = "자체 장면"
L["The scene this trigger starts."] = "이 발동 조건이 시작하는 장면."
L["only if |cffffd100%s|r"] = "|cffffd100%s|r일 때만"
L["after waiting %g sec"] = "%g초 기다린 뒤"
L["at most once every %g sec"] = "최대 %g초마다 한 번"
L["%d%% of the time"] = "%d%% 확률로"
L["Priority %d."] = "우선순위 %d."
L["This trigger isn't there any more: pick one on the Triggers tab."] = "이 발동 조건은 이제 없습니다: 발동 조건 탭에서 고르세요."
L["Starts when |cffffd100%s|r"] = "시작 조건: |cffffd100%s|r"
L["after %g sec"] = "%g초 뒤"
L["when %s starts"] = "%s 시작 시"
L["%s. Ends: |cffffd100%s|r. Priority %d."] = "%s. 끝: |cffffd100%s|r. 우선순위 %d."
L["No scene uses it yet."] = "아직 쓰는 장면이 없습니다."

-- Camera/ShotsPage.lua
L["Make your own version of a standing-still camera with your own sway and zoom."] = "흔들림과 확대/축소를 직접 정한 나만의 정지 카메라를 만듭니다."
L["Lets scenes set to a shot play it with its own sway and zoom."] = "샷으로 설정한 장면이 그 샷의 흔들림과 확대/축소로 재생되게 합니다."
L["Makes a new shot, starting from the cozy camera's numbers."] = "아늑한 카메라의 값에서 시작하는 새 샷을 만듭니다."
L["Plays this shot now; press again or move to stop."] = "이 샷을 지금 재생합니다. 다시 누르거나 움직이면 멈춥니다."
L["Deletes this shot; scenes that played it go back to its camera."] = "이 샷을 삭제합니다. 이를 재생하던 장면은 원래 카메라로 돌아갑니다."
L["The camera this shot moves like."] = "이 샷이 따라 움직이는 카메라."

-- Visions/QuestTalk.lua
L["Fade if another addon competes: it stays away while another addon has the conversation"] = "다른 애드온과 겹치면 흐리기: 다른 애드온이 대화를 맡는 동안 나타나지 않습니다"

-- Atmosphere/Tint.lua
L["A soft, hazy warm glow over the scene."] = "화면 위에 부드럽고 뿌연 따뜻한 빛."
L["Changes color through the day, from blue nights to golden evenings."] = "푸른 밤부터 황금빛 저녁까지 하루 동안 색이 바뀝니다."
L["A mood color for the zone you're in, like pale blue in snow or sandy in deserts."] = "눈 지역의 옅은 파랑이나 사막의 모래색처럼 현재 지역의 분위기 색."
L["The zone's mood and the time-of-day color together."] = "지역 분위기 색과 시간대 색을 함께."
L["My color"] = "내 색상"
L["Death Vision"] = "Death Vision"
L["The world dims and goes cold while you're dead, and dark edges close in. It shows with the death camera."] = "죽어 있는 동안 세상이 어둡고 차갑게 변하며 가장자리가 어둡게 조여 옵니다. 죽음 카메라와 함께 표시됩니다."
L["Turns Death Vision on or off."] = "Death Vision을 켜거나 끕니다."
L["How dim the world and how dark the edges get."] = "세상이 얼마나 어두워지고 가장자리가 얼마나 짙어지는지."
L["How long the dark edges take to close in after you die."] = "죽은 뒤 어두운 가장자리가 조여 오는 데 걸리는 시간."
L["How far the dark edges reach in from each side of the screen."] = "어두운 가장자리가 화면 각 변에서 안쪽으로 들어오는 거리."
L["The dark edges lift as you walk back to your body."] = "시체로 걸어 돌아가면 어두운 가장자리가 걷힙니다."
L["Shows the death screen for a few seconds (close the settings to see it)."] = "죽음 화면을 몇 초간 보여 줍니다 (보려면 설정을 닫으세요)."
L["Also on death"] = "죽었을 때도"
L["The game's gray screen:"] = "게임의 회색 화면:"
L["Graphics Boost"] = "그래픽 향상"
L["Opens the Graphics Boost page."] = "그래픽 향상 페이지를 엽니다."

-- Atmosphere/LowHealth.lua
L["How the low-health screen edges look."] = "생명력이 낮을 때 화면 가장자리 모양."
L["Turns this page's look settings on or off."] = "이 페이지의 모양 설정을 켜거나 끕니다."
L["Shows your health falling in the preview and on screen."] = "미리 보기와 화면에서 생명력이 떨어지는 모습을 보여 줍니다."
L["The look of the edges; Auto picks one for your class and spec."] = "가장자리 모양. 자동이면 직업과 전문화에 맞는 것을 고릅니다."
L["Undoes your changes to this theme."] = "이 테마에서 바꾼 내용을 되돌립니다."
L["Gives you this theme as text to share."] = "이 테마를 공유용 텍스트로 줍니다."
L["Makes a blank theme of your own."] = "빈 나만의 테마를 만듭니다."
L["Sound:"] = "소리:"
L["The sound that plays as your health runs low."] = "생명력이 낮아질 때 재생되는 소리."
L["Ambient volume"] = "주변 소리 음량"
L["How loud the sound plays compared to your ambient volume."] = "주변 소리 음량에 비해 이 소리를 얼마나 크게 재생할지."
L["How strong the whole effect is."] = "전체 효과의 강도."
L["How far in from the edges the whole effect comes."] = "전체 효과가 가장자리에서 안쪽으로 들어오는 거리."
L["How bright the art's colors are."] = "그림 색상의 밝기."
L["Black at 0%, the theme's color at 100%."] = "0%는 검정, 100%는 테마 색상."
L["The edges flash when a big hit lands."] = "큰 피해를 받으면 가장자리가 번쩍입니다."
L["Flash darkness"] = "번쩍임 어둠"
L["How much darker the edges get in a flash, on top of Darkness."] = "번쩍일 때 어둠에 더해 가장자리가 얼마나 더 어두워지는지."
L["Flash color"] = "번쩍임 색상"
L["How much a flash tints the edges."] = "번쩍일 때 가장자리에 색을 입히는 정도."
L["Flash fade"] = "번쩍임 사라지기"
L["Seconds a flash takes to fade."] = "번쩍임이 사라지는 데 걸리는 초."
L["The theme's art that soaks in from the edges."] = "가장자리에서 스며드는 테마 그림."
L["How far in it comes from the left and right sides."] = "왼쪽과 오른쪽 가장자리에서 안쪽으로 들어오는 거리."
L["The sparks that float over the edges."] = "가장자리 위를 떠다니는 불꽃."
L["Wisps of heat rise from the bottom of the screen as you weaken."] = "약해질수록 화면 아래에서 열기가 피어오릅니다."
L["A swirl that turns over the screen as you weaken."] = "약해질수록 화면 위에서 도는 소용돌이."
L["The kind of swirl."] = "소용돌이 종류."
L["How fast the swirl turns; below 0 turns the other way."] = "소용돌이가 도는 속도. 0보다 작으면 반대로 돕니다."
L["The game's own screen effects closing in at the edges."] = "가장자리에서 조여 오는 게임 기본 화면 효과."
L["A wave of the game's art creeps in on each heartbeat."] = "심장이 뛸 때마다 게임 그림이 물결처럼 스며듭니다."
L["Which of the game's effects shows."] = "표시할 게임 효과."
L["What shape cuts the effect to the screen's edges."] = "효과를 화면 가장자리에 맞춰 자르는 모양."
L["Tint the effect to your theme or keep its own colors."] = "효과에 테마 색을 입히거나 원래 색을 유지합니다."
L["A second game effect over the first."] = "첫 번째 위에 겹치는 두 번째 게임 효과."
L["The game's effects slide slowly under their edge."] = "게임 효과가 가장자리 밑에서 천천히 흘러갑니다."
L["One of the game's full-screen effects closing in as you weaken."] = "약해질수록 조여 오는 게임의 전체 화면 효과 중 하나."
L["As your health drops, the screen's edges close in so you feel it."] = "생명력이 떨어지면 화면 가장자리가 조여 와서 체감할 수 있습니다."
L["Turns Vitals Vision on or off."] = "Vitals Vision을 켜거나 끕니다."
L["The screen's edges close in as your health drops."] = "생명력이 떨어지면 화면 가장자리가 조여 옵니다."
L["How strong the edges are out of a fight."] = "전투 밖에서 가장자리의 강도."
L["Ramp up"] = "가속"
L["Higher makes the edges close in slowly at first, then faster."] = "높을수록 가장자리가 처음엔 천천히, 나중엔 빠르게 조여 옵니다."
L["Replace game's low health flash setting"] = "게임의 생명력 낮음 번쩍임 설정 대신 사용"
L["When the game's Do Not Flash Screen at Low Health setting is ticked, the edges don't show."] = "게임의 '생명력이 낮을 때 화면 깜박이지 않기' 설정에 체크되어 있으면 가장자리가 표시되지 않습니다."
L["Game setting: |cffff8000no flash|r (edges off while followed)"] = "게임 설정: |cffff8000번쩍임 없음|r (따르는 동안 가장자리 꺼짐)"
L["Game setting: |cff00ff00flash on|r"] = "게임 설정: |cff00ff00번쩍임 켜짐|r"
L["How fast the edges close in when your health drops."] = "생명력이 떨어질 때 가장자리가 조여 오는 속도."
L["How fast the edges lift when you're healed."] = "치유받을 때 가장자리가 걷히는 속도."
L["Smaller hits that add up to this much of your health count as a big one."] = "작은 피해라도 합쳐서 생명력의 이만큼이 되면 큰 피해로 칩니다."

-- Atmosphere/TeleportVision.lua
L["Teleport Vision"] = "Teleport Vision"
L["shown"] = "표시됨"
L["A Hearthstone or teleport cast, with its scene playing"] = "귀환석이나 순간이동 시전, 장면 재생 중"
L["Teleport Vision colors: stopped."] = "Teleport Vision 색상: 중지됨."
L["Teleport Vision colors: all %d shown."] = "Teleport Vision 색상: %d개 모두 표시함."
L["Teleport Vision colors: %d specs, %d seconds each (/cine teleport colors again to stop)."] = "Teleport Vision 색상: 전문화 %d개, 각 %d초 (멈추려면 /cine teleport colors 다시 입력)."
L["A glowing portal rim closes in around you as you cast a Hearthstone or teleport."] = "귀환석이나 순간이동을 시전하면 빛나는 차원문 테두리가 주위를 조여 옵니다."
L["Shows a glowing portal around you as you cast a teleport."] = "순간이동을 시전할 때 주위에 빛나는 차원문을 보여 줍니다."
L["The portal's color: your class and spec's, any class's, or your own."] = "차원문 색상: 내 직업과 전문화의 색, 아무 직업의 색, 또는 직접 고른 색."
L["Clouds in its color swirl outside the rim, filling the screen."] = "테두리 밖에서 같은 색의 구름이 소용돌이치며 화면을 채웁니다."
L["Black edges close in from the sides as the cast fills."] = "시전이 차오를수록 검은 가장자리가 양옆에서 조여 옵니다."
L["How long before the cast ends the screen goes fully black; 0 turns it off."] = "시전이 끝나기 얼마 전에 화면이 완전히 검게 될지. 0이면 끕니다."
L["Fades out your cast bar early in the cast, so the portal shows its progress."] = "시전 초반에 시전 바를 흐리게 해서 차원문이 진행 상황을 보여 주게 합니다."
L["Fades out the tooltip while you cast."] = "시전하는 동안 툴팁을 흐리게 합니다."

-- UI/PersonalResources.lua
L["In Calm Timer now: you came back to life, until your health and power are full"] = "지금 진정 타이머 중: 되살아났으며, 생명력과 자원이 가득 찰 때까지"
L["In Calm Timer now: you fell, %d sec ago (till the Calm Timer runs out)"] = "지금 진정 타이머 중: %d초 전에 떨어졌습니다 (진정 타이머가 끝날 때까지)"
L["In Calm Timer now: you cast a spell that costs health, %d sec ago (till the Calm Timer runs out)"] = "지금 진정 타이머 중: %d초 전에 생명력을 쓰는 주문을 시전했습니다 (진정 타이머가 끝날 때까지)"
L["In Calm Timer now: you lost health out of a fight, %d sec ago (till the Calm Timer runs out)"] = "지금 진정 타이머 중: %d초 전에 전투 밖에서 생명력을 잃었습니다 (진정 타이머가 끝날 때까지)"
L["In Calm Timer now: your last fight, %d sec ago (till the Calm Timer runs out)"] = "지금 진정 타이머 중: 마지막 전투가 %d초 전 (진정 타이머가 끝날 때까지)"
L["In Calm Timer now: after a fight, a fall, Life Tap or resurrecting"] = "지금 진정 타이머 중: 전투, 낙하, 생명력 전환 또는 부활 후"
L["In Calm Timer"] = "진정 타이머 중"
L["In a fight it goes by %s for %s"] = "전투 중에는 %s에 따라 %s 기준"
