-- Style/LetterboxStyle.lua
L["Brings the bars in for a few seconds when you find a new place."] = "새 장소를 발견하면 몇 초간 바를 보여 줍니다."
L["How long the bars stay when you find a new place."] = "새 장소를 발견했을 때 바가 머무는 시간."
L["Makes the tint stronger on this client, whose brighter world shows it less."] = "월드가 더 밝아 색조가 덜 보이는 이 클라이언트에서 색조를 더 강하게 합니다."
L["How strongly the time-of-day color applies."] = "시간대 색상이 적용되는 강도."
L["Lets the tint's strength slowly drift up and down by this much."] = "색조 강도가 이만큼 천천히 오르내리게 합니다."
L["Dim the world map"] = "세계 지도 어둡게"
