L["Match the tint"] = "색조에 맞추기"
L["Dims the world map only as much as the tint is dark right now."] = "지금 색조가 어두운 만큼만 세계 지도를 어둡게 합니다."
L["How long one zone's mood takes to fade out and the next to fade in."] = "한 지역의 분위기가 사라지고 다음 지역의 분위기가 나타나는 데 걸리는 시간."
L["An untinted gap between two zones' moods while you're flying."] = "비행하는 동안 두 지역 분위기 사이의 색조 없는 구간."
L["Shows all through CineMode, fights and the Calm Timer after them."] = "전투와 전투 후 진정 타이머를 포함해 CineMode 내내 표시합니다."
L["How the letterbox bars at the top and bottom of the screen look."] = "화면 위아래 레터박스 바의 모양."
L["On: the bars look as this page says; off: Cinematic's plain black bars."] = "켜면: 이 페이지 설정대로 바가 보입니다. 끄면: Cinematic의 단순한 검은 바."
L["Makes the space between the bars the shape of a film, on any screen."] = "어떤 화면에서든 바 사이의 공간을 영화 화면 비율로 만듭니다."
L["How long the bars take to come in or go; 0 matches the UI's fade."] = "바가 들어오거나 나가는 데 걸리는 시간. 0이면 UI 흐리기에 맞춥니다."

