L["Shows the time of day when you log in."] = "접속할 때 시간대를 표시합니다."
L["No Zone or Subzone cards while on a flight path."] = "비행 경로 이용 중에는 지역 또는 하위 지역 카드가 없습니다."
L["Shows one line under the game's zone name instead of a card."] = "카드 대신 게임의 지역 이름 아래에 한 줄을 표시합니다."
L["Big words across the middle of the screen, like YOU DIED."] = "YOU DIED처럼 화면 가운데를 가로지르는 큰 글자."
