L["Turns this page's combat text on or off."] = "이 페이지의 전투 문자를 켜거나 끕니다."
L["Plays sample hits on the nameplate over and over."] = "이름표에 예시 타격을 반복해서 보여 줍니다."
L["Turn our numbers on, and hide the game's."] = "Cinematic 숫자를 켜고 게임 숫자를 숨깁니다."
L["Each text starts out as the one it's under; a change to one changes only that one."] = "각 문자는 처음에 위의 항목을 따릅니다. 하나를 바꾸면 그것만 바뀝니다."
L["Who draws the numbers"] = "숫자를 그리는 쪽"
L["Ours follow the Look tab. The game's are the game's own, as it draws them."] = "Cinematic 숫자는 모양 탭을 따릅니다. 게임 기본은 게임이 그리는 그대로입니다."
L["Your damage"] = "내 피해량"
L["Your hits on enemies."] = "적에게 준 내 타격."
L["Your heals"] = "내 치유량"
L["Your heals on friendly nameplates."] = "아군 이름표에 표시되는 내 치유."
L["Your pet's damage"] = "소환수 피해량"
L["Your pet's hits on enemies."] = "적에게 준 소환수의 타격."
L["In a group, ours show only your pet's spells, not its swings."] = "파티에서는 Cinematic 숫자가 소환수의 평타는 빼고 주문만 보여 줍니다."
L["Ours, in the Look tab's look."] = "Cinematic 숫자, 모양 탭의 모양으로."
L["The game's own numbers, as it draws them."] = "게임이 그리는 그대로의 게임 숫자."
L["Set XP and other floating text to The game's first: with it on None the game draws none of its numbers."] = "먼저 '경험치 및 기타 전투 문자'를 게임 기본으로 설정하세요: 없음이면 게임이 숫자를 하나도 그리지 않습니다."
L["No numbers for these."] = "이것들은 숫자 없음."
L["Game's in groups"] = "파티에선 게임 기본"
L["Ours when you're on your own; the game's own, every pet hit, in a group or raid."] = "혼자일 때는 Cinematic 숫자, 파티나 공격대에서는 게임 기본으로 소환수의 모든 타격."
L["You're in a group: only your pet's spells show now. Its swings look the same as your group's."] = "파티 중입니다: 지금은 소환수의 주문만 표시됩니다. 소환수의 평타는 파티원의 것과 똑같아 보입니다."
L["In a group, ours show only your pet's spells: its swings look the same as your group's. The game's shows every pet hit, in its own look."] = "파티에서는 Cinematic 숫자가 소환수의 주문만 보여 줍니다: 평타는 파티원의 것과 똑같아 보이기 때문입니다. 게임 기본은 소환수의 모든 타격을 자체 모양으로 보여 줍니다."
L["Hiding XP hides all the game's floating text, so these would show nothing: %s."] = "경험치를 숨기면 게임의 전투 문자가 모두 숨겨지므로 이것들은 아무것도 표시되지 않습니다: %s."
L["Switch them to ours"] = "Cinematic 숫자로 바꾸기"
L["XP and other floating text"] = "경험치 및 기타 전투 문자"
L["The game's floating text: XP gained and the rest."] = "게임의 전투 문자: 얻은 경험치 등."
L["Hides all the game's floating text, its numbers too; needs a full game restart."] = "숫자를 포함한 게임의 전투 문자를 모두 숨깁니다. 게임을 완전히 다시 시작해야 합니다."
L["Restart the game to apply. With it hidden the game draws none of its numbers, so The game's is grayed out in the rows above."] = "적용하려면 게임을 다시 시작하세요. 숨기면 게임이 숫자를 하나도 그리지 않으므로 위 줄에서 게임 기본이 회색으로 표시됩니다."
L["Restart the game to apply: until then the game's floating text stays hidden."] = "적용하려면 게임을 다시 시작하세요: 그때까지는 게임의 전투 문자가 숨겨진 채로 있습니다."
L["With it hidden the game draws none of its numbers, so The game's is grayed out in the rows above."] = "숨기면 게임이 숫자를 하나도 그리지 않으므로 위 줄에서 게임 기본이 회색으로 표시됩니다."
L["None hides all of the game's floating text, its numbers too, and takes a game restart."] = "없음은 숫자를 포함한 게임의 전투 문자를 모두 숨기며, 게임을 다시 시작해야 합니다."
L["Quick settings"] = "빠른 설정"
L["Each row sets many texts at once; change any of them after in the table below."] = "각 줄이 여러 문자를 한 번에 설정합니다. 그 뒤 아래 표에서 무엇이든 바꿀 수 있습니다."
L["Spell colors"] = "주문 색상"
L["All yellow"] = "모두 노랑"
L["Every spell in the game's yellow."] = "모든 주문을 게임 기본 노랑으로."
L["Every spell is the game's yellow again."] = "모든 주문이 다시 게임 기본 노랑입니다."
L["By school"] = "계열별"
L["Each spell school in its own color: fire orange, frost blue."] = "주문 계열마다 고유한 색: 화염은 주황, 냉기는 파랑."
L["Each spell school has its own color: see Spells in the table."] = "주문 계열마다 고유한 색입니다: 표의 주문을 보세요."
L["Shows"] = "표시"
L["Every text on."] = "모든 문자 켜기."
L["Every text is on."] = "모든 문자가 켜져 있습니다."
L["Crits and misses"] = "치명타와 빗나감"
L["Only your crits and misses; plain hits and heals off."] = "치명타와 빗나감만. 일반 타격과 치유는 끔."
L["Plain hits and heals are off, crits and misses on: switch any back in the table."] = "일반 타격과 치유는 꺼지고 치명타와 빗나감은 켜졌습니다: 표에서 무엇이든 다시 켤 수 있습니다."
L["No swings"] = "평타 없음"
