-- Style/UnitStyle.lua
L["Unit Frame Style"] = "유닛 프레임 스타일"
L["How your player, target, focus, pet and party frames look."] = "플레이어, 대상, 주시 대상, 소환수, 파티 프레임의 모양."
L["On: the unit frames look as this page says; off: the game's own look."] = "켜면: 이 페이지 설정대로 유닛 프레임이 보입니다. 끄면: 게임 기본 모양."
L["By health"] = "생명력에 따라"
L["Its color below at full health, turning to the At half and Empty colors as health drops."] = "생명력이 가득할 때 아래 색이며, 생명력이 떨어지면 절반 및 바닥 색으로 바뀝니다."
L["The health bar's color, for Custom (at full health, for By health)."] = "생명력 바 색상. 사용자 지정용 (생명력에 따라는 가득할 때의 색)."
L["At half"] = "절반"
