L["Empty"] = "바닥"
L["Its color as health runs out, for By health."] = "생명력에 따라: 생명력이 바닥날 때의 색."
L["The font for names."] = "이름 글꼴."
L["The theme's"] = "테마 설정"
L["Long names:"] = "긴 이름:"
