-- Visions/EmoteVision.lua
L["Pick an emote, %s targets them, or move to cancel"] = "감정 표현을 고르세요. %s(으)로 대상 지정, 움직이면 취소"
L["Pick an emote, %s closes, or move to cancel"] = "감정 표현을 고르세요. %s(으)로 닫기, 움직이면 취소"
L["%s: answer with the face buttons"] = "%s: 페이스 버튼으로 대답"
L["grouped with you"] = "나와 같은 파티"
L["is stalking you"] = "당신을 따라다니는 중"
L["rested and ready"] = "휴식 완료, 준비됨"
L["Works Everywhere"] = "어디서나 작동"
L["Nameplates Required"] = "이름표 필요"
L["The cards that need the other player's nameplate: CineMode keeps it for them."] = "상대 플레이어의 이름표가 필요한 카드: CineMode가 이를 위해 이름표를 유지합니다."
L["Which cards to skip, how long they stay, and the player menu."] = "건너뛸 카드, 머무는 시간, 플레이어 메뉴."
L["Click: play it at them. Right-click: play it at no one."] = "클릭: 상대에게 하기. 오른쪽 클릭: 대상 없이 하기."
L["Already on the menu (or the menu is full). Right-click: play it."] = "이미 메뉴에 있음 (또는 메뉴가 가득 참). 오른쪽 클릭: 하기."
L["Click: add it to the menu. Right-click: play it."] = "클릭: 메뉴에 추가. 오른쪽 클릭: 하기."
L["%d of %d: the menu is full"] = "%d/%d: 메뉴가 가득 참"
L["%d of %d on the menu"] = "메뉴에 %d/%d"
L["That player"] = "그 플레이어"
L["Emote at %s"] = "%s에게 감정 표현"
L["More Emotes"] = "감정 표현 더 보기"
L["All Emotes..."] = "모든 감정 표현..."
L["On the menu itself, in this order. The rest stay under More Emotes."] = "메뉴에 이 순서대로 바로 표시됩니다. 나머지는 '감정 표현 더 보기' 아래에 있습니다."
L["Move this emote up the menu."] = "이 감정 표현을 메뉴에서 위로 옮깁니다."
L["Take it off the menu."] = "메뉴에서 뺍니다."
L["Adds an emote to the menu, up to six."] = "메뉴에 감정 표현을 추가합니다. 최대 6개."
L["The menu's emotes as they come."] = "메뉴의 감정 표현을 처음 상태로."
L["Fire button at the cursor"] = "커서에 불 버튼"
L["A fire icon under the cursor too: click it to do one of this card's emotes."] = "커서 아래에도 불 아이콘을 표시합니다: 클릭하면 이 카드의 감정 표현 하나를 합니다."
L["Cursor reach from the middle"] = "가운데로부터 커서 범위"
L["How close to the middle of the screen the cursor must be on a campfire."] = "모닥불 위의 커서가 화면 가운데에 얼마나 가까워야 하는지."
L["Reach widens the longer you hover"] = "오래 올려 둘수록 범위 확대"
L["The longer you hover a campfire, the further from the middle it may be."] = "모닥불에 오래 마우스를 올릴수록 가운데에서 더 멀어도 됩니다."
L["Words in a name that mark it as a campfire, separated by commas."] = "이름에 들어 있으면 모닥불로 보는 단어, 쉼표로 구분."
L["Show a timer while you rest"] = "휴식 중 타이머 표시"
L["A bar in the top bar fills up over the minute Camp Benefits takes."] = "야영지 혜택까지 걸리는 1분 동안 위쪽 바 안의 막대가 차오릅니다."
L["Shows this moment's card; with someone targeted, its buttons emote at them."] = "이 순간의 카드를 보여 줍니다. 누군가를 대상으로 잡고 있으면 버튼이 그 대상에게 감정 표현을 합니다."
L["Adds an emote button to this card, up to six."] = "이 카드에 감정 표현 버튼을 추가합니다. 최대 6개."
L["When someone emotes at you, a small card lets you answer with one click."] = "누군가 나에게 감정 표현을 하면 작은 카드가 떠서 한 번의 클릭으로 대답할 수 있습니다."
L["Turns all Emote Vision cards on or off."] = "모든 Emote Vision 카드를 켜거나 끕니다."
L["Pick the moments that show a card and the emotes on it."] = "카드를 보여 줄 순간과 카드의 감정 표현을 고르세요."
L["These cards need the other player's nameplate. CineMode keeps friendly players' nameplates for them, hidden; outside it they show only while your friendly nameplates are on."] = "이 카드에는 상대 플레이어의 이름표가 필요합니다. CineMode는 이를 위해 아군 플레이어의 이름표를 숨긴 채 유지합니다. CineMode 밖에서는 아군 이름표가 켜져 있을 때만 표시됩니다."
L["Turns these cards on or off."] = "이 카드를 켜거나 끕니다."
L["When the cards show and for how long."] = "카드가 표시되는 때와 시간."
L["Ignores the same person doing the same thing again for a few minutes."] = "같은 사람이 같은 행동을 반복하면 몇 분 동안 무시합니다."
L["How long a card stays; hovering holds it."] = "카드가 머무는 시간. 마우스를 올리면 유지됩니다."
L["Gamepad answer button:"] = "게임패드 대답 버튼:"
L["In gamepad mode, press this to answer a card with the face buttons."] = "게임패드 모드에서 이것을 누르면 페이스 버튼으로 카드에 대답합니다."
L["Player menu"] = "플레이어 메뉴"
L["Menu:"] = "메뉴:"
L["Emotes on the right-click menu"] = "오른쪽 클릭 메뉴에 감정 표현"
L["Adds an Emote section to the right-click menu on friendly players."] = "아군 플레이어의 오른쪽 클릭 메뉴에 감정 표현 항목을 추가합니다."
L["Pick its style, look and position."] = "스타일, 모양, 위치를 고르세요."
L["How far right and up the card sits."] = "카드를 오른쪽과 위로 얼마나 옮길지."
L["Lets you drag the card; click Done when finished."] = "카드를 끌어 옮길 수 있게 합니다. 끝나면 완료를 클릭하세요."
L["Puts the card back in its starting spot."] = "카드를 처음 위치로 되돌립니다."

-- Visions/DamageVision.lua
L["Shows your damage race with the player just ahead of you, from the game's damage meter."] = "게임 피해량 측정기를 바탕으로 바로 앞 순위 플레이어와의 피해량 경쟁을 보여 줍니다."
L["Turns Damage Vision on or off."] = "Damage Vision을 켜거나 끕니다."
L["Damage meter:"] = "피해량 측정기:"
L["Only while it's faded out"] = "흐려져 있을 때만"
L["Shows it only while the game's damage meter is faded out."] = "게임 피해량 측정기가 흐려져 있을 때만 표시합니다."
L["Picks when everyone's damage starts back at 0."] = "모두의 피해량이 0부터 다시 시작하는 때를 고릅니다."
L["Plays a made-up 25-second fight; close the settings to see it."] = "가상의 25초 전투를 재생합니다. 보려면 설정을 닫으세요."
L["Shows your full damage report for the run."] = "이번 던전 진행의 전체 피해량 보고서를 보여 줍니다."
L["The most rows to show."] = "표시할 최대 줄 수."
L["Pick its type, look and position."] = "종류, 모양, 위치를 고르세요."
L["Turns this page's look on, or uses the plain look when off."] = "이 페이지의 모양을 켭니다. 끄면 기본 모양을 씁니다."
L["The bar's color while you're behind."] = "뒤처져 있을 때 바 색상."
L["The bar's color once you lead."] = "앞서 있을 때 바 색상."
L["How dark the panel behind it is; 0 for none."] = "뒤 패널의 어둡기. 0이면 없음."
L["The color of your place."] = "내 순위 색상."
L["How far right and up from the screen's middle it sits."] = "화면 가운데에서 오른쪽과 위로 얼마나 떨어져 있을지."
L["Sits:"] = "위치:"
L["Where you put it"] = "직접 둔 곳"
L["At the X and Y below (or where you drag it with Move)."] = "아래 X와 Y 위치 (또는 이동으로 끌어다 놓은 곳)."
L["Over the damage meter"] = "피해량 측정기 위"
L["Sits over the game's damage meter window."] = "게임 피해량 측정기 창 위에 놓입니다."
L["Drag the box to move it; right-click to reset."] = "상자를 끌어 옮기고, 오른쪽 클릭으로 초기화합니다."

-- Slash.lua
L["toggle CineMode"] = "CineMode 켜기/끄기"
L["turn Cinematic off completely: asks, then turns it off in the AddOns list and reloads"] = "Cinematic을 완전히 끄기: 확인한 뒤 애드온 목록에서 끄고 다시 불러옵니다"
L["open the settings at the setting or page with those words, e.g. /cine find minimap"] = "그 단어가 들어간 설정이나 페이지로 설정 열기, 예: /cine find minimap"
L["open a page by its names from the left list down, e.g. /cine find ui visibility minimap"] = "왼쪽 목록의 이름을 위에서부터 따라 페이지 열기, 예: /cine find ui visibility minimap"
L["look only on those pages, e.g. /cine find Style||Names fade time"] = "그 페이지에서만 찾기, 예: /cine find Style||Names fade time"
L["show or hide the keyboard map: what each of your keys does (with words: find them on it)"] = "키보드 배치도 표시/숨기기: 각 키가 하는 일 (단어를 붙이면 배치도에서 찾기)"
L["a window listing every frame, whether it's showing right now, and why"] = "모든 창과 지금 표시 중인지, 그 이유를 보여 주는 창"
L["why friendly nameplates near you are showing, as text to copy and send us"] = "근처 아군 이름표가 왜 표시되는지, 복사해서 보낼 수 있는 텍스트로"
L["record what the addon costs, results on the Profiler page (deep: in detail, stop: end it early)"] = "애드온의 부하를 기록, 결과는 프로파일러 페이지에 (deep: 자세히, stop: 일찍 끝내기)"
L["has the addon hit any errors? Lists them, newest last"] = "애드온에 오류가 있었나요? 최신 것이 마지막에 오도록 나열합니다"
L["no errors in the log"] = "기록에 오류가 없습니다"
