L["Closes the gaps so the shown icons sit centered."] = "빈틈을 메워 보이는 아이콘을 가운데 정렬합니다."
L["Keeps the Cooldown Manager up until every cooldown in this bar is ready."] = "이 바의 모든 재사용 대기시간이 준비될 때까지 재사용 대기시간 관리자를 유지합니다."
L["Stacks and time left"] = "중첩과 남은 시간"
L["Shows stacks and time left on tracked buff icons."] = "추적 중인 강화 효과 아이콘에 중첩과 남은 시간을 표시합니다."
L["Click for this bar's own settings."] = "클릭하면 이 바만의 설정이 나옵니다."
L["Click for this spell's own settings."] = "클릭하면 이 주문만의 설정이 나옵니다."
L["Sets spells you haven't set yourself based on what they cost."] = "직접 설정하지 않은 주문을 소모 자원에 따라 설정합니다."
L["Resets every icon setting to the active profile's."] = "모든 아이콘 설정을 현재 프로필 값으로 초기화합니다."
L["Highlights mobs, NPCs and objects you still need for a quest."] = "퀘스트에 아직 필요한 몹, NPC, 사물을 강조합니다."
L["Turns Quest Vision on or off."] = "Quest Vision을 켜거나 끕니다."
L["What shows of mobs and NPCs you still need for a quest."] = "퀘스트에 아직 필요한 몹과 NPC에서 무엇을 보여 줄지."
L["Shows a gold ! beside the nameplates of quest mobs and NPCs."] = "퀘스트 몹과 NPC의 이름표 옆에 금색 !를 표시합니다."
L["Cinematic's wins"] = "Cinematic 우선"
L["Questie's wins"] = "Questie 우선"
L["Both show"] = "둘 다 표시"
L["Which quest icon shows when both Cinematic and Questie mark the same unit."] = "Cinematic과 Questie가 같은 유닛을 표시할 때 보여 줄 퀘스트 아이콘."
L["Questie's icons"] = "Questie 아이콘"
L["The quest mark on friendly NPCs; click to pick another."] = "아군 NPC의 퀘스트 표시. 클릭해서 다른 것을 고르세요."
L["The quest mark on enemies; click to pick another."] = "적의 퀘스트 표시. 클릭해서 다른 것을 고르세요."
L["A big button for the nearest tracked quest's usable item."] = "가장 가까운 추적 퀘스트의 사용 아이템을 위한 큰 버튼."
L["Fade if another addon competes"] = "다른 애드온과 겹치면 흐리기"
L["Hides this button when another addon shows one for the same item."] = "다른 애드온이 같은 아이템의 버튼을 보여 주면 이 버튼을 숨깁니다."
L["The quest object in front of you glows gold."] = "앞에 있는 퀘스트 사물이 금색으로 빛납니다."
L["Hide object icons"] = "사물 아이콘 숨기기"
L["Hides the game's icon on the object your interact key would use."] = "상호작용 키가 사용할 사물 위의 게임 아이콘을 숨깁니다."
L["Closes talking heads you've already seen."] = "이미 본 말하는 얼굴 창을 닫습니다."
L["NPC dialogue shows in a speech bubble and reply list instead of the game's windows."] = "NPC 대화를 게임 창 대신 말풍선과 대답 목록으로 보여 줍니다."
L["Hides Cinematic's dialogue when another dialogue addon is running."] = "다른 대화 애드온이 작동 중이면 Cinematic의 대화를 숨깁니다."
L["Game's window with a controller"] = "컨트롤러 사용 시 게임 창"
L["Uses the game's own dialogue windows in gamepad mode."] = "게임패드 모드에서는 게임의 대화 창을 씁니다."
L["Where the speech bubble goes."] = "말풍선 위치."
L["How far the bubble stays from the top of the screen."] = "말풍선이 화면 위쪽에서 떨어진 거리."
L["Stops the camera drifting while you talk."] = "대화하는 동안 카메라가 흘러가지 않게 합니다."
L["What the bubble and card do while the camera moves."] = "카메라가 움직이는 동안 말풍선과 카드가 하는 일."
L["The shop window opens where the talk was."] = "상점 창이 대화가 있던 자리에 열립니다."
L["Shows group loot rolls in a window instead of only in chat."] = "파티 전리품 주사위를 대화창뿐 아니라 별도 창에 보여 줍니다."
L["Party/Dungeon"] = "파티/던전"
L["The rules while you're in a party: in a dungeon, a delve or out in the world."] = "파티에 있을 때의 규칙: 던전, 구렁, 필드."
L["The rules while you're in a raid group."] = "공격대에 있을 때의 규칙."
