L["Shows a panel with the winner once the item's won."] = "아이템 주인이 정해지면 획득자를 담은 패널을 보여 줍니다."
L["All Rolls"] = "모든 주사위"
L["Whether items of this quality get a panel in the window."] = "이 품질의 아이템에 창의 패널을 줄지."
L["Usable"] = "사용 가능"
L["Only items you can use get a panel."] = "사용할 수 있는 아이템만 패널을 받습니다."
L["Hide Uncounted"] = "미집계 숨기기"
L["Hides Greed and Transmog rolls once someone rolls Need."] = "누군가 입찰을 굴리면 차비와 형상변환 주사위를 숨깁니다."
L["Max Players"] = "최대 플레이어"
L["Each item lists at most this many players' rolls; click its panel to see everyone."] = "아이템마다 최대 이만큼의 플레이어 주사위를 나열합니다. 패널을 클릭하면 모두 볼 수 있습니다."
L["Separate window"] = "별도 창"
L["Where the roll window shows: beside the game's roll frames or as its own window."] = "주사위 창의 위치: 게임 주사위 창 옆 또는 별도 창."
L["Popup location"] = "팝업 위치"
L["How many items the window shows at once; the oldest goes when a new one drops."] = "창에 한 번에 보이는 아이템 수. 새 아이템이 나오면 가장 오래된 것이 빠집니다."
L["Always show your roll"] = "내 주사위 항상 표시"
L["Your own roll always shows on an item's panel."] = "아이템 패널에 내 주사위를 항상 표시합니다."
L["Always show rolls I need"] = "입찰한 아이템 주사위 항상 표시"
L["Items you roll Need on always show everyone's rolls."] = "입찰을 굴린 아이템은 항상 모두의 주사위를 보여 줍니다."
L["Shows the extra lines under an item's players, like who passed, in a party, raid or both."] = "파티, 공격대 또는 둘 다에서 아이템 플레이어 아래에 누가 포기했는지 같은 추가 줄을 보여 줍니다."
L["Show selected count"] = "선택 수 표시"
L["Stays hidden while another addon handles loot rolls."] = "다른 애드온이 전리품 주사위를 처리하는 동안에는 숨긴 채로 있습니다."
L["In CineMode, shows the nameplates of players dueling near you so you can watch."] = "CineMode에서 근처 결투 중인 플레이어의 이름표를 보여 줘서 구경할 수 있게 합니다."
L["Shows an icon beside a duelist's nameplate while they're crowd controlled."] = "결투자가 군중 제어를 당하는 동안 이름표 옆에 아이콘을 표시합니다."
