L["Shows a duelist's instant spells as icons beside their nameplate."] = "결투자의 즉시 시전 주문을 이름표 옆 아이콘으로 보여 줍니다."
L["Spell names"] = "주문 이름"
L["The newest instant spell's name shows above its icon."] = "가장 최근 즉시 시전 주문의 이름을 아이콘 위에 표시합니다."
L["Hides other players' duels while you're in one."] = "내가 결투 중일 때는 다른 플레이어의 결투를 숨깁니다."
L["Shows a 30-second pretend duel between nearby players so you can see how it looks."] = "어떻게 보이는지 확인할 수 있게 근처 플레이어 사이의 30초짜리 가상 결투를 보여 줍니다."
L["Party and raid frames show only the members who need healing."] = "파티 및 공격대 창에 치유가 필요한 구성원만 보여 줍니다."
