L["How much of a hidden tank still shows."] = "숨겨진 방어 전담이 여전히 보이는 정도."
L["A healer shows once their health drops below this."] = "치유 전담은 생명력이 이 아래로 떨어지면 나타납니다."
L["How much of a hidden healer still shows."] = "숨겨진 치유 전담이 여전히 보이는 정도."
L["A damage dealer shows once their health drops below this."] = "공격 전담은 생명력이 이 아래로 떨어지면 나타납니다."
L["How much of a hidden damage dealer and the group titles still show."] = "숨겨진 공격 전담과 파티 제목이 여전히 보이는 정도."
