L["Where tooltips show: their usual corner or by your mouse."] = "툴팁 위치: 평소 모서리 또는 마우스 옆."
L["How long you hover before the After column's parts show."] = "이후 열의 부분이 보이기 전에 마우스를 올려 두는 시간."
