L["Level (friends)"] = "레벨 (아군)"
L["The level line of players and NPCs you can't attack."] = "공격할 수 없는 플레이어와 NPC의 레벨 줄."
L["Level (enemies)"] = "레벨 (적)"
L["The level line of players and NPCs you can attack."] = "공격할 수 있는 플레이어와 NPC의 레벨 줄."
L["Right-click hints"] = "오른쪽 클릭 안내"
L["The right-click hint lines on frames and items."] = "창과 아이템의 오른쪽 클릭 안내 줄."
L["Quest objective mobs"] = "퀘스트 목표 몹"
L["These tooltips show the After column's parts right away."] = "이 툴팁은 이후 열의 부분을 바로 보여 줍니다."
L["No wait for"] = "대기 없음"
L["Filtered tooltips"] = "거른 툴팁"
L["Tooltips with these names never show in CineMode."] = "이 이름의 툴팁은 CineMode에서 절대 보이지 않습니다."
L["Type a tooltip's top line as the game shows it."] = "툴팁의 첫 줄을 게임에 표시되는 그대로 입력하세요."
L["CineMode hides these addons' frames: pick which show, and when."] = "CineMode는 이 애드온들의 창을 숨깁니다: 어떤 것을 언제 보일지 고르세요."
L["Turns fading of other addons' frames in CineMode on or off."] = "CineMode에서 다른 애드온 창을 흐리게 하는 기능을 켜거나 끕니다."
L["Show %s the whole time in CineMode.%s"] = "CineMode 내내 %s을(를) 표시합니다.%s"
L["Switching an addon's support on or off counts after a reload. Reload now?"] = "애드온 지원을 켜거나 끈 것은 다시 불러온 뒤 적용됩니다. 지금 다시 불러오시겠습니까?"
L["Turns Cinematic's support for this addon on or off after a reload."] = "다시 불러온 뒤 이 애드온에 대한 Cinematic의 지원을 켜거나 끕니다."
L["Gives every row on this page the Default row's settings."] = "이 페이지의 모든 줄에 기본 줄의 설정을 줍니다."
L["Addons you install later start always shown in CineMode."] = "나중에 설치하는 애드온은 CineMode에서 항상 표시되는 상태로 시작합니다."
L["Smart Find looks for new addons' frames in the background for a while."] = "스마트 찾기가 한동안 백그라운드에서 새 애드온의 창을 찾습니다."
L["Looks for other addons' frames that nothing fades yet."] = "아직 아무것도 흐리게 하지 않는 다른 애드온의 창을 찾습니다."
L["Load all"] = "모두 불러오기"
L["Loads every frame on this list that isn't loaded yet, as Load does for one."] = "이 목록에서 아직 불러오지 않은 모든 창을 불러옵니다 (불러오기를 하나씩 하는 것과 같음)."
L["Load"] = "불러오기"
L["Puts it on the Loaded tab, under its addon, with the Default row's settings."] = "기본 줄 설정으로 불러옴 탭의 해당 애드온 아래에 넣습니다."
L["Hover over frames, then click Stop to add them to the list."] = "창 위에 마우스를 올린 다음, 멈추기를 클릭해 목록에 추가하세요."
L["Type part of a frame's or addon's name to find it."] = "찾으려면 창이나 애드온 이름의 일부를 입력하세요."
L["Turns CineMode on or off."] = "CineMode를 켜거나 끕니다."
L["Hides the whole UI but keeps the CineMode effects."] = "UI 전체를 숨기지만 CineMode 효과는 유지합니다."
L["Takes a screenshot with the UI hidden."] = "UI를 숨기고 스크린샷을 찍습니다."
L["Turns the visual effects on or off."] = "화면 효과를 켜거나 끕니다."
L["Shows or hides the letterbox bars."] = "레터박스 바를 표시하거나 숨깁니다."
L["Hides the cursor until you move the mouse."] = "마우스를 움직일 때까지 커서를 숨깁니다."
L["Reloads the UI."] = "UI를 다시 불러옵니다."
L["Opens or closes Cinematic's settings."] = "Cinematic 설정을 열거나 닫습니다."
L["Keyboard map"] = "키보드 배치도"
L["Hold or tap to see what each key on your keyboard does."] = "누르고 있거나 살짝 누르면 키보드의 각 키가 하는 일을 볼 수 있습니다."
L["Hold to open a wheel of all your wheels."] = "누르고 있으면 모든 휠을 모은 휠을 엽니다."
L["Hold to open a wheel of your cameras."] = "누르고 있으면 카메라 휠을 엽니다."
L["Hold to open a wheel of the game's menu buttons."] = "누르고 있으면 게임 메뉴 버튼 휠을 엽니다."
L["Hold to open a wheel of raid target markers."] = "누르고 있으면 공격대 대상 징표 휠을 엽니다."
L["Hold to open a wheel of ground markers; only in a group."] = "누르고 있으면 바닥 징표 휠을 엽니다. 파티에서만."
L["Hold to open a wheel that turns the visions on or off."] = "누르고 있으면 Vision을 켜고 끄는 휠을 엽니다."
L["Turns Damage Vision on or off (its Enable Page switch)."] = "Damage Vision을 켜거나 끕니다 ('페이지 사용' 스위치)."
L["Turns Teleport Vision on or off (its Enable Page switch)."] = "Teleport Vision을 켜거나 끕니다 ('페이지 사용' 스위치)."
L["Turns Emote Vision on or off (its Enable Page switch)."] = "Emote Vision을 켜거나 끕니다 ('페이지 사용' 스위치)."
L["Turns Card Vision on or off (its Enable Page switch)."] = "Card Vision을 켜거나 끕니다 ('페이지 사용' 스위치)."
L["Starts the AFK camera now."] = "자리 비움 카메라를 지금 시작합니다."
L["Starts the cozy camera now."] = "아늑한 카메라를 지금 시작합니다."
L["Starts the vista camera now."] = "풍경 카메라를 지금 시작합니다."
L["Starts the fish camera now."] = "낚시 카메라를 지금 시작합니다."
L["Starts the tele camera now."] = "순간이동 카메라를 지금 시작합니다."
L["Starts or stops the RP walk camera."] = "RP 걷기 카메라를 시작하거나 멈춥니다."
L["Starts or stops the auto-run camera."] = "자동 달리기 카메라를 시작하거나 멈춥니다."
L["Pretends you're dead for 30 seconds to test the death camera."] = "죽음 카메라를 시험하려고 30초 동안 죽은 척합니다."
L["Turns the Shoulder Cam on or off (its Enable Page switch)."] = "어깨 카메라를 켜거나 끕니다 ('페이지 사용' 스위치)."
L["Stops whichever of Cinematic's cameras is running now, however it started."] = "어떻게 시작됐든 지금 도는 Cinematic 카메라를 멈춥니다."
L["Targets the last NPC who spoke near you."] = "근처에서 마지막으로 말한 NPC를 대상으로 잡습니다."
L["Scene keys"] = "장면 키"
L["Plays your scenes that use this key."] = "이 키를 쓰는 장면을 재생합니다."
L["Hold to see tooltips that are hidden."] = "누르고 있으면 숨긴 툴팁을 봅니다."
L["hidden"] = "숨김"
L["Click, then press a key; right-click to clear."] = "클릭한 다음 키를 누르세요. 오른쪽 클릭으로 지웁니다."
L["Keys for Cinematic, the same as in the game's Key Bindings under AddOns."] = "Cinematic의 단축키. 게임의 단축키 설정 > 애드온에 있는 것과 같습니다."
L["Key groups"] = "키 그룹"
L["New key group"] = "새 키 그룹"
L["A key group of your own: name it, set its key and pick its frames."] = "나만의 키 그룹: 이름을 붙이고, 키를 정하고, 창을 고르세요."
L["Deletes this group and its keys."] = "이 그룹과 그 키를 삭제합니다."
L["Pick the frames this group's key shows and hides."] = "이 그룹의 키가 표시하고 숨길 창을 고르세요."
L["Key group %d"] = "키 그룹 %d"
L["No frames yet: pick them on the right"] = "아직 창이 없습니다: 오른쪽에서 고르세요"
L["Pick frames (%d)"] = "창 고르기 (%d)"
L["Reset frame keys after a reload"] = "다시 불러오면 창 키 초기화"
L["Frames you showed or hid with their keys go back to normal after a reload."] = "키로 표시하거나 숨긴 창이 다시 불러온 뒤 원래대로 돌아갑니다."
L["Back to their Show in rows"] = "'표시 장소' 줄 설정으로 돌아감"
L["A profile is a whole set of settings you can switch between."] = "프로필은 바꿔 가며 쓸 수 있는 설정 묶음입니다."
L["Pick, add and share profiles."] = "프로필을 고르고, 추가하고, 공유하세요."
L["Change parts of the active profile."] = "현재 프로필의 일부를 바꿉니다."
L["This character keeps its own profile."] = "이 캐릭터는 자체 프로필을 유지합니다."
L["Makes a copy of the active profile as your own."] = "현재 프로필의 사본을 내 것으로 만듭니다."
L["Brings back an older copy of a profile."] = "프로필의 이전 사본을 되살립니다."
L["Adds a profile someone shared with you."] = "다른 사람이 공유한 프로필을 추가합니다."
L["Gives you the active profile as text to share."] = "현재 프로필을 공유용 텍스트로 줍니다."
L["Write what the active profile is for."] = "현재 프로필의 용도를 적으세요."
L["Puts the active profile back to how you last saved it."] = "현재 프로필을 마지막으로 저장한 상태로 되돌립니다."
L["Saves the active profile as the point Reset goes back to."] = "현재 프로필을 초기화 시 돌아갈 지점으로 저장합니다."
L["Your own profile."] = "나만의 프로필."
L["Customizing %s"] = "%s 사용자 지정 중"
L["Customize %s"] = "%s 사용자 지정"
L["Frames in the same group come up together when you mouse over any of them."] = "같은 그룹의 창은 그중 하나에 마우스를 올리면 함께 나타납니다."
L["How long a frame stays after your mouse leaves it."] = "마우스가 떠난 뒤 창이 머무는 시간."
L["All parts"] = "모든 부분"
L["%s (all parts)"] = "%s (모든 부분)"
L["%s (%d of %d parts)"] = "%s (%d/%d 부분)"
L["Which parts of this frame come up with this group."] = "이 그룹과 함께 나타날 이 창의 부분."
L["When this group works: any time, in combat or out of combat."] = "이 그룹이 작동하는 때: 언제나, 전투 중, 전투 밖."
L["Turns this group on or off."] = "이 그룹을 켜거나 끕니다."
L["Hover reach"] = "마우스오버 범위"
L["%d px"] = "%d px"
L["How close the mouse must come to this group's buttons to bring it up."] = "이 그룹을 불러오려면 마우스가 버튼에 얼마나 가까이 와야 하는지."
L["Floating text changes after you fully restart the game (/reload isn't enough). The same goes for getting it back: until a full restart it stays hidden, even with Cinematic turned off."] = "전투 문자는 게임을 완전히 다시 시작해야 바뀝니다 (/reload로는 부족합니다). 되돌릴 때도 마찬가지입니다: 완전히 다시 시작할 때까지는 Cinematic을 꺼도 숨겨진 채로 있습니다."

