L["Shows how much of your computer's time Cinematic uses."] = "Cinematic이 컴퓨터 자원을 얼마나 쓰는지 보여 줍니다."
L["Turn on to track and record the addon's CPU use."] = "켜면 애드온의 CPU 사용량을 추적하고 기록합니다."
L["Records the addon's CPU use while you play; click again to stop."] = "플레이하는 동안 애드온의 CPU 사용량을 기록합니다. 다시 클릭하면 멈춥니다."
L["Times nearly every function too, which makes everything read a bit higher."] = "거의 모든 함수의 시간도 재므로 모든 수치가 조금 높게 나옵니다."
L["Starts recording right away instead of when you close the settings."] = "설정을 닫을 때가 아니라 바로 기록을 시작합니다."
L["Copies a text report to send us."] = "저희에게 보낼 텍스트 보고서를 복사합니다."

